window.pourfolioCocktailCatalog=[{"name":"Americano","spirit":"aperitif","base":"Aperitif","family":"aperitivo highball","spec":"30 ml bitter aperitivo; 30 ml sweet vermouth; soda water","method":"Build over ice in a rocks glass; top soda; orange or lemon.","taste":"Gentle bitterness, wine sweetness, lively bubbles.","history":"First called Milano-Torino in some accounts, reflecting ingredient origins; “Americano” became associated with its popularity among American visitors.","glass":"Coupe / rocks","origin":"Historical note: First called Milano-Torino in some accounts, reflecting ingredient origins; “Americano” became associated with its popularity among American visitors.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Aviation","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 15 ml maraschino liqueur; 15 ml lemon; 7.5 ml crème de violette","method":"Shake with ice; fine-strain into chilled coupe.","taste":"Floral, tart, juniper-led, cherry-like.","history":"Printed in Hugo Ensslin’s 1916 recipes. Early specs included crème de violette; later versions omitted it when the liqueur was hard to find.","glass":"Coupe / rocks","origin":"Historical note: Printed in Hugo Ensslin’s 1916 recipes. Early specs included crème de violette; later versions omitted it when the liqueur was hard to find.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bee's Knees","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 22.5 ml lemon; 22.5 ml honey syrup","method":"Shake with ice; fine-strain; lemon twist.","taste":"Floral honey, bright lemon, botanical finish.","history":"A Prohibition-era gin sour; honey helped soften rough spirits. “Bee’s knees” was slang for excellent.","glass":"Coupe / rocks","origin":"Historical note: A Prohibition-era gin sour; honey helped soften rough spirits. “Bee’s knees” was slang for excellent.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bellini","spirit":"wine","base":"Wine","family":"sparkling","spec":"100 ml Prosecco; 50 ml white peach purée","method":"Add peach purée to a chilled flute; top slowly with Prosecco and stir gently.","taste":"Fresh peach, soft texture, dry sparkle.","history":"Created by Giuseppe Cipriani at Harry’s Bar, Venice, around 1948; named for the painter Giovanni Bellini.","glass":"Coupe / rocks","origin":"Historical note: Created by Giuseppe Cipriani at Harry’s Bar, Venice, around 1948; named for the painter Giovanni Bellini.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Between the Sheets","spirit":"rum","base":"Rum","family":"sour","spec":"29.6 ml Brandy; 29.6 ml Light rum; 29.6 ml Triple sec; 29.6 ml Lemon juice","method":"Pour all ingredients into shaker with ice cubes, shake, strain into chilled cocktail glass.","taste":"Bright citrus, orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Between the Sheets. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Black Russian","spirit":"vodka","base":"Vodka","family":"spirit-forward","spec":"50 ml vodka; 20 ml coffee liqueur","method":"Build over ice in a rocks glass; stir gently.","taste":"Coffee sweetness and clean, warming spirit.","history":"Often credited to bartender Gustave Tops at Brussels’ Hotel Metropole around 1949; the account is widely repeated, though archival detail is limited.","glass":"Coupe / rocks","origin":"Historical note: Often credited to bartender Gustave Tops at Brussels’ Hotel Metropole around 1949; the account is widely repeated, though archival detail is limited.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bloody Mary","spirit":"vodka","base":"Vodka","family":"savory","spec":"45 ml vodka; 90 ml tomato juice; 15 ml lemon; Worcestershire, hot sauce, salt, pepper","method":"Roll or gently stir with ice; serve in a tall glass with savory garnish.","taste":"Savory, tangy, gently spicy; seasoning is adjustable.","history":"Often associated with 1920s Paris and bartender Fernand Petiot, though the drink evolved and the name has competing stories.","glass":"Coupe / rocks","origin":"Historical note: Often associated with 1920s Paris and bartender Fernand Petiot, though the drink evolved and the name has competing stories.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Boulevardier","spirit":"whiskey","base":"Whiskey","family":"bitter aperitivo","spec":"45 ml bourbon or rye; 30 ml bitter aperitivo; 30 ml sweet vermouth","method":"Stir with ice; strain over a large cube or into a coupe; orange peel.","taste":"Rich, bittersweet, warming, oak and orange.","history":"Published by Erskine Gwynne in Paris in 1927. A whiskey-led relative of the Negroni, though its exact earlier history is unclear.","glass":"Coupe / rocks","origin":"Historical note: Published by Erskine Gwynne in Paris in 1927. A whiskey-led relative of the Negroni, though its exact earlier history is unclear.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bramble","spirit":"gin","base":"Gin","family":"modern sour","spec":"50 ml gin; 25 ml lemon; 12.5 ml syrup; 15 ml crème de mûre float","method":"Shake gin, lemon and syrup; strain over crushed ice; drizzle blackberry liqueur.","taste":"Bright lemon, crushed ice, ripe blackberry.","history":"Created by Dick Bradsell in London in the 1980s, inspired by foraging for blackberries on the Isle of Wight.","glass":"Coupe / rocks","origin":"Historical note: Created by Dick Bradsell in London in the 1980s, inspired by foraging for blackberries on the Isle of Wight.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Brandy Crusta","spirit":"brandy","base":"Brandy","family":"sour","spec":"60 ml brandy; 15 ml orange curaçao; 10 ml maraschino liqueur; 20 ml lemon juice; 7.5 ml simple syrup; 2 dashes aromatic bitters","method":"Shake with ice; strain into a sugar-rimmed, citrus-oil-lined coupe. Express a lemon peel and set it inside.","taste":"Brandy fruit, lemon, orange and dry spice; sweet-tart with a fragrant citrus-oil rim.","history":"Often credited to Joseph Santini in New Orleans in the 1850s and later recorded by Jerry Thomas. Early printed recipes support the family, though exact first-service details vary.","glass":"Coupe / cocktail","origin":"Often credited to Joseph Santini in New Orleans in the 1850s and later recorded by Jerry Thomas. Early printed recipes support the family, though exact first-service details vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Caipirinha","spirit":"cachaça","base":"Cachaça","family":"sour","spec":"60 ml cachaça; 1 lime; 2 tsp fine sugar","method":"Muddle lime wedges gently with sugar; add cachaça and ice; stir.","taste":"Fresh lime oils, grassy cane, direct sweetness.","history":"Brazil’s national cocktail, made with cachaça. Its exact origin is uncertain; early medicinal lime-and-spirit preparations are sometimes cited.","glass":"Coupe / rocks","origin":"Historical note: Brazil’s national cocktail, made with cachaça. Its exact origin is uncertain; early medicinal lime-and-spirit preparations are sometimes cited.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Casino","spirit":"gin","base":"Gin","family":"sour","spec":"59.1 ml Gin; 1.2 ml Maraschino liqueur; 1.2 ml Lemon juice; 2 dashes Orange bitters; 1 Cherry","method":"Pour all ingredients into shaker with ice cubes. Shake well. Strain into chilled cocktail glass. Garnish with a lemon twist and a maraschino cherry. Serve without a straw.","taste":"Bright citrus, orange peel, rounded sweetness, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Casino. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Champagne Cocktail","spirit":"brandy","base":"Brandy","family":"sour","spec":"1 sugar cube; 2–3 dashes aromatic bitters; 10 ml Cognac (optional); 90 ml chilled Champagne or dry sparkling wine","method":"Add bitters to the sugar cube in a flute; add Cognac if desired; top slowly with sparkling wine; express lemon peel.","taste":"Bubbles lift bitters and citrus oils; the sugar dissolves gradually, giving a dry-to-sweeter evolving sip.","history":"Champagne cocktails appear in 19th-century bartending literature, including Jerry Thomas’s 1862 guide. Specs vary; “Champagne Cocktail” is a style, not one fixed formula.","glass":"Champagne flute","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Clover Club","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"45 ml gin; 20 ml lemon juice; 15 ml raspberry syrup; 15 ml dry vermouth; 15 ml egg white (optional)","method":"Dry shake if using egg white; shake again with ice; fine-strain into a chilled coupe.","taste":"Silky berry, bright lemon and juniper; dry vermouth gives a drier, more structured finish.","history":"Named for the Philadelphia men’s club where it was served around the turn of the 20th century. It appears in early 20th-century cocktail books; exact first recipe and attribution vary.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Corpse Reviver No. 2","spirit":"gin","base":"Gin","family":"equal-parts sour","spec":"22.5 ml gin; 22.5 ml orange liqueur; 22.5 ml Lillet Blanc; 22.5 ml lemon; absinthe rinse","method":"Rinse chilled glass with absinthe; shake other ingredients; fine-strain.","taste":"Citrus, orange blossom, light wine and anise.","history":"A pre-Prohibition “reviver” family; Harry Craddock’s 1930 Savoy Cocktail Book popularized this version, with a wry warning about overuse.","glass":"Coupe / rocks","origin":"Historical note: A pre-Prohibition “reviver” family; Harry Craddock’s 1930 Savoy Cocktail Book popularized this version, with a wry warning about overuse.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Cosmopolitan","spirit":"vodka","base":"Vodka","family":"sour","spec":"40 ml citrus vodka; 15 ml triple sec; 15 ml lime; 30 ml cranberry","method":"Shake with ice; strain into chilled coupe; orange zest.","taste":"Citrus-led, tart-sweet, cranberry-colored.","history":"A family of cranberry-and-citrus drinks preceded its 1990s revival. Multiple bartenders claim versions; the popular modern spec was refined in the US bar scene.","glass":"Coupe / rocks","origin":"Historical note: A family of cranberry-and-citrus drinks preceded its 1990s revival. Multiple bartenders claim versions; the popular modern spec was refined in the US bar scene.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Cuba Libre","spirit":"rum","base":"Rum","family":"spirit-forward","spec":"50 ml light or lightly aged rum; 10 ml fresh lime juice; 100 ml cola","method":"Build over fresh ice in a highball; stir gently once. Express a lime wedge and serve.","taste":"Sweet cola and cane meet lime’s sharp acid and peel aroma; refreshing, lightly spiced and bittersweet.","history":"The name is associated with Cuba’s independence era and the early 20th-century Cuba–US connection. The familiar toast story is widely repeated, but exact origin details are difficult to prove.","glass":"Highball glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Daiquiri","spirit":"rum","base":"Rum","family":"sour","spec":"60 ml white rum; 25 ml lime juice; 15 ml simple syrup","method":"Shake hard with ice; fine-strain into a chilled coupe.","taste":"Bright, dry-tart, clean cane and lime.","history":"Named for Daiquirí, Cuba. The modern sour style developed around the turn of the 20th century; its precise invention story is disputed.","glass":"Coupe / rocks","origin":"Historical note: Named for Daiquirí, Cuba. The modern sour style developed around the turn of the 20th century; its precise invention story is disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Dark 'n' Stormy","spirit":"dark rum","base":"Dark rum","family":"highball","spec":"60 ml dark rum; 120 ml ginger beer; 10 ml lime juice","method":"Build ginger beer and lime over fresh ice in a highball; float rum or stir gently. Lime wedge.","taste":"Molasses, ginger heat, lime and lively carbonation; dry to gently sweet.","history":"A Bermuda rum-and-ginger-beer serve associated with Gosling’s rum. The name and trademark history are more certain than any single inventor story.","glass":"Highball","origin":"A Bermuda rum-and-ginger-beer serve associated with Gosling’s rum. The name and trademark history are more certain than any single inventor story.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"De La Louisiane","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"45 ml rye whiskey; 20 ml sweet vermouth; 20 ml Bénédictine; 2 dashes Peychaud’s bitters; absinthe rinse","method":"Rinse a chilled coupe with absinthe. Stir remaining ingredients with ice; strain and garnish with a brandied cherry.","taste":"Rye spice, herbal honey, bittersweet wine and anise perfume.","history":"A New Orleans cocktail recorded in Stanley Clisby Arthur’s 1937 Famous New Orleans Drinks and How to Mix ’Em; it is named for the Hotel de la Louisiane.","glass":"Coupe","origin":"A New Orleans cocktail recorded in Stanley Clisby Arthur’s 1937 Famous New Orleans Drinks and How to Mix ’Em; it is named for the Hotel de la Louisiane.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Dirty Martini","spirit":"vodka","base":"Vodka","family":"bitter aperitivo","spec":"60 ml gin or vodka; 10 ml dry vermouth; 5–10 ml olive brine, to taste","method":"Stir with ice; strain into a chilled glass. Garnish with an olive.","taste":"Saline, savory and spirit-forward; brine adds salt and olive character while muting some botanical detail.","history":"The dirty style is a later variation on the evolving Martini, using olive brine for savory salinity. Exact invention date and inventor are not reliably settled; recipes vary widely.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Dry Martini","spirit":"gin","base":"Gin","family":"bitter aperitivo","spec":"60 ml gin; 10 ml dry vermouth; optional 1 dash orange bitters; lemon twist or olive","method":"Stir with ice until very cold and properly diluted; strain into a chilled cocktail glass. Garnish with expressed lemon oil or an olive.","taste":"Dry, crisp and botanical; the gin leads while vermouth adds wine texture and aroma. Ratio and garnish change the profile.","history":"The Martini evolved from 19th-century gin-and-vermouth cocktails. Its name and recipe shifted through the late 19th and 20th centuries; no single uncontested inventor or fixed original ratio is established.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"El Presidente","spirit":"white rum","base":"White rum","family":"spirit-forward","spec":"45 ml Cuban-style white rum; 25 ml blanc vermouth; 10 ml dry curaçao; 5 ml grenadine","method":"Stir with ice until very cold; strain into a chilled coupe; express orange peel.","taste":"Elegant, dry-leaning rum, orange and gentle pomegranate sweetness.","history":"A Cuban cocktail popularized in the early 20th century and associated with Havana’s presidential era. Competing recipes and naming stories exist.","glass":"Coupe","origin":"A Cuban cocktail popularized in the early 20th century and associated with Havana’s presidential era. Competing recipes and naming stories exist.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Espresso Martini","spirit":"vodka","base":"Vodka","family":"modern sour","spec":"50 ml vodka; 30 ml coffee liqueur; 30 ml fresh espresso; 10 ml simple syrup","method":"Shake hard with ice; fine-strain into a chilled coupe; garnish three coffee beans.","taste":"Roasted coffee, silky foam, bittersweet finish.","history":"Created by Dick Bradsell in London in the 1980s; originally called the Vodka Espresso.","glass":"Coupe / rocks","origin":"Historical note: Created by Dick Bradsell in London in the 1980s; originally called the Vodka Espresso.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Fernet and Coke","spirit":"fernet amaro","base":"Fernet amaro","family":"highball","spec":"45 ml Fernet-style amaro; 120 ml cola; 10 ml lime juice, optional","method":"Build over ice in a highball; top with cola and lift gently once.","taste":"Assertive menthol, herbs and bitter roots softened by sweet cola.","history":"A contemporary Argentine bar staple commonly called Fernet con Coca; its exact first bartender is not reliably established.","glass":"Highball","origin":"A contemporary Argentine bar staple commonly called Fernet con Coca; its exact first bartender is not reliably established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"French 75","spirit":"gin","base":"Gin","family":"sparkling","spec":"30 ml gin; 15 ml lemon; 15 ml simple syrup; 60 ml Champagne","method":"Shake first three; strain into flute; top with sparkling wine.","taste":"Bright, dry, lifted bubbles with botanical structure.","history":"Named for the French 75 mm field gun, likely reflecting its lively effect. The drink appears in early 20th-century sources; recipes vary.","glass":"Coupe / rocks","origin":"Historical note: Named for the French 75 mm field gun, likely reflecting its lively effect. The drink appears in early 20th-century sources; recipes vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"French Connection","spirit":"brandy","base":"Brandy","family":"spirit-forward","spec":"35 ml Cognac; 35 ml amaretto","method":"Build over ice in a rocks glass; stir gently.","taste":"Soft, almond-like sweetness with warming grape spirit.","history":"A simple two-ingredient after-dinner drink popularized in the 1970s; no reliably documented single inventor.","glass":"Coupe / rocks","origin":"Historical note: A simple two-ingredient after-dinner drink popularized in the 1970s; no reliably documented single inventor.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"French Martini","spirit":"vodka","base":"Vodka","family":"modern sour","spec":"45 ml vodka; 15 ml raspberry liqueur; 45 ml pineapple juice","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Pineapple foam, berry aroma, soft sweetness.","history":"A 1980s–90s cocktail associated with New York bartender Keith McNally’s Balthazar-era cocktail revival; attribution and exact date vary.","glass":"Coupe / rocks","origin":"Historical note: A 1980s–90s cocktail associated with New York bartender Keith McNally’s Balthazar-era cocktail revival; attribution and exact date vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Gin Basil Smash","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml Gin; 20 ml Lemon Juice; 20 ml Sugar Syrup; Whole Basil","method":"Muddle Basil leaves (~ 10) with Suggar Syrup in a shaker. Add Gin an Lemon Juice.\r\nFilter and serve in a tumbler with ice","taste":"Bright citrus, rounded sweetness, herbal aroma. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Gin Basil Smash. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Highball glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Gin Fizz","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 22.5 ml lemon juice; 15 ml simple syrup; 60–90 ml chilled soda water","method":"Shake gin, lemon and syrup with ice; strain into a chilled highball; top with soda.","taste":"Citrus-bright, dry-refreshing and effervescent, with juniper carried by a soft foamless sparkle.","history":"Fizz drinks were established in 19th-century American bartending and appeared in Jerry Thomas-era literature. The family developed many variants; the exact first Gin Fizz is uncertain.","glass":"Highball glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Gin Rickey","spirit":"gin","base":"Gin","family":"highball","spec":"45 ml gin; 15 ml lime juice; 90 ml soda water","method":"Build over ice in a highball; squeeze lime and drop shell in; top soda.","taste":"Dry, tart, crisp, low sweetness.","history":"A Washington, D.C. drink associated with lobbyist Colonel Joe Rickey in the late 19th century; early versions could use whiskey.","glass":"Coupe / rocks","origin":"Historical note: A Washington, D.C. drink associated with lobbyist Colonel Joe Rickey in the late 19th century; early versions could use whiskey.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Gimlet","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 22.5 ml fresh lime juice; 15 ml simple syrup (or adjusted lime cordial)","method":"Shake with ice; strain into a chilled coupe, or serve over ice in a rocks glass.","taste":"Focused lime, crisp juniper and restrained sweetness; cordial versions are rounder and more perfumed.","history":"The Gimlet is documented in early 20th-century print and linked in popular stories to British naval lime rations. That origin tale is not conclusive; early recipes and modern versions differ.","glass":"Martini Glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Gold Rush","spirit":"bourbon","base":"Bourbon","family":"sour","spec":"60 ml bourbon; 25 ml lemon juice; 20 ml honey syrup","method":"Shake with ice; strain over a large cube or into a chilled coupe; lemon twist.","taste":"Honeyed oak and warm grain lifted by bright lemon.","history":"Created by T. J. Siegal at New York’s Milk & Honey in the early 2000s; a modern sour built from the Bee’s Knees idea.","glass":"Rocks / coupe","origin":"Created by T. J. Siegal at New York’s Milk & Honey in the early 2000s; a modern sour built from the Bee’s Knees idea.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Hanky Panky","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"45 ml gin; 45 ml sweet vermouth; 7.5 ml Fernet-Branca","method":"Stir with ice; strain into a chilled coupe; express orange peel.","taste":"Botanical gin, vermouth richness and a firm menthol-bitter finish.","history":"Credited to Ada Coleman at the American Bar, London, in the early 20th century; the story is associated with actor Charles Hawtrey.","glass":"Coupe","origin":"Credited to Ada Coleman at the American Bar, London, in the early 20th century; the story is associated with actor Charles Hawtrey.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Harvey Wallbanger","spirit":"vodka","base":"Vodka","family":"highball","spec":"45 ml vodka; 90 ml orange juice; 15 ml vanilla-anise liqueur float","method":"Build vodka and orange juice over ice; float liqueur; garnish orange.","taste":"Juicy orange with vanilla and herbal-anise finish.","history":"A 1970s American cocktail associated with a Galliano promotional campaign; the surfer-character origin story is likely marketing lore.","glass":"Coupe / rocks","origin":"Historical note: A 1970s American cocktail associated with a Galliano promotional campaign; the surfer-character origin story is likely marketing lore.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Hemingway Daiquiri","spirit":"white rum","base":"White rum","family":"sour","spec":"60 ml white rum; 15 ml maraschino liqueur; 15 ml lime juice; 30 ml grapefruit juice; 5 ml simple syrup, optional","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Dry rum, tart lime, bittersweet grapefruit and cherry-like maraschino.","history":"A dry Daiquiri variation associated with Ernest Hemingway and Havana’s El Floridita. The classic bar recipe evolved; literary lore should not be mistaken for a single fixed original.","glass":"Coupe","origin":"A dry Daiquiri variation associated with Ernest Hemingway and Havana’s El Floridita. The classic bar recipe evolved; literary lore should not be mistaken for a single fixed original.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Hot Toddy","spirit":"whiskey","base":"Whiskey","family":"spirit-forward","spec":"45 ml whiskey; 15 ml honey; 20 ml lemon juice; 90–120 ml hot water; optional cinnamon","method":"Stir honey with hot water to dissolve; add whiskey and lemon; serve warm with a lemon peel.","taste":"Warm grain, honey and lemon; fragrant and gently sweet with a bright, soothing impression.","history":"“Toddy” has older British and South Asian linguistic and drink histories; the hot whiskey version evolved over time. No single modern inventor is firmly established.","glass":"Irish coffee cup","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Jungle Bird","spirit":"rum","base":"Rum","family":"tropical bitter","spec":"45 ml dark or aged rum; 22.5 ml bitter aperitivo; 45 ml pineapple; 15 ml lime; 15 ml syrup","method":"Shake with ice; strain over fresh ice; garnish pineapple.","taste":"Tropical fruit meets assertive bitter orange and rum.","history":"Credited to the Kuala Lumpur Hilton’s Aviary bar in 1973. Often noted for pairing rum with a bitter Italian aperitivo.","glass":"Coupe / rocks","origin":"Historical note: Credited to the Kuala Lumpur Hilton’s Aviary bar in 1973. Often noted for pairing rum with a bitter Italian aperitivo.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Kir Royale","spirit":"wine","base":"Wine","family":"sparkling","spec":"10 ml crème de cassis; 90 ml Champagne or dry sparkling wine","method":"Pour cassis into a flute; top gently with chilled sparkling wine.","taste":"Blackcurrant richness with dry, lively bubbles.","history":"A sparkling variation of the Kir, associated with Félix Kir, mayor of Dijon, in postwar France.","glass":"Coupe / rocks","origin":"Historical note: A sparkling variation of the Kir, associated with Félix Kir, mayor of Dijon, in postwar France.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Last Word","spirit":"gin","base":"Gin","family":"equal-parts sour","spec":"22.5 ml gin; 22.5 ml green Chartreuse; 22.5 ml maraschino; 22.5 ml lime","method":"Shake with ice; fine-strain into chilled coupe.","taste":"Herbal, tart, sweet, pungent and tightly balanced.","history":"A pre-Prohibition Detroit Athletic Club drink, published in the 1910s. It was revived in the modern cocktail renaissance; details of its first service are sparse.","glass":"Coupe / rocks","origin":"Historical note: A pre-Prohibition Detroit Athletic Club drink, published in the 1910s. It was revived in the modern cocktail renaissance; details of its first service are sparse.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Lemon Drop","spirit":"vodka","base":"Vodka","family":"spirit-forward","spec":"1 1/2 shot Vodka; 1 1/2 shot Cointreau; Juice of 1 wedge Lemon","method":"Shake and strain into a chilled cocktail glass rimmed with sugar.","taste":"Bright citrus, orange peel. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Lemon Drop. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Long Island Iced Tea","spirit":"vodka","base":"Vodka","family":"highball","spec":"15 ml each vodka, gin, white rum, tequila and orange liqueur; 25 ml lemon; 20 ml syrup; cola to top","method":"Shake spirits, citrus and syrup briefly; strain over fresh ice; top cola.","taste":"Citrusy, sweet, cola-like; deceptively spirit-heavy.","history":"Competing origin tales place versions in 1920s Tennessee or 1970s Long Island; no single claim is settled.","glass":"Coupe / rocks","origin":"Historical note: Competing origin tales place versions in 1920s Tennessee or 1970s Long Island; no single claim is settled.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Mai Tai","spirit":"rum","base":"Rum","family":"tiki sour","spec":"30 ml aged Jamaican rum; 30 ml aged agricole rum; 15 ml dry curaçao; 15 ml orgeat; 30 ml lime; 7.5 ml rich syrup","method":"Shake with crushed ice; open pour into a rocks glass; garnish mint and spent lime shell.","taste":"Dry, nutty, lime-bright and rum-forward; not a generic fruit punch.","history":"Created by Victor J. “Trader Vic” Bergeron in Oakland in 1944, though Donn Beach and others developed related earlier tropical drinks; the modern spec has many variations.","glass":"Coupe / rocks","origin":"Historical note: Created by Victor J. “Trader Vic” Bergeron in Oakland in 1944, though Donn Beach and others developed related earlier tropical drinks; the modern spec has many variations.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Manhattan","spirit":"whiskey","base":"Whiskey","family":"spirit-forward","spec":"60 ml rye whiskey; 30 ml sweet vermouth; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe. Cherry optional.","taste":"Silky, bittersweet, spice-forward.","history":"A New York cocktail documented in the late 19th century. The Manhattan Club origin tale is famous but debated; vermouth cocktails were part of a broader era.","glass":"Coupe / rocks","origin":"Historical note: A New York cocktail documented in the late 19th century. The Manhattan Club origin tale is famous but debated; vermouth cocktails were part of a broader era.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Margarita","spirit":"tequila","base":"Tequila","family":"sour","spec":"50 ml blanco tequila; 25 ml orange liqueur; 25 ml lime juice","method":"Shake with ice; strain over fresh ice or serve up. Salt rim optional.","taste":"Citrusy, tart, agave-led, lightly sweet.","history":"Its origin is contested, with several 1930s–50s stories across Mexico and the US. It belongs to the Daisy family; no origin story is universally proven.","glass":"Coupe / rocks","origin":"Historical note: Its origin is contested, with several 1930s–50s stories across Mexico and the US. It belongs to the Daisy family; no origin story is universally proven.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Martinez","spirit":"old tom gin","base":"Old Tom gin","family":"spirit-forward","spec":"45 ml Old Tom gin; 45 ml sweet vermouth; 5 ml maraschino liqueur; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; express lemon peel.","taste":"Soft juniper, wine, cherry and warm spice; a bridge between early gin cocktails and the Martini.","history":"A 19th-century cocktail family documented in early bartending books. Its exact origin and whether it preceded the Martini remain debated.","glass":"Coupe","origin":"A 19th-century cocktail family documented in early bartending books. Its exact origin and whether it preceded the Martini remain debated.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Mary Pickford","spirit":"rum","base":"Rum","family":"tropical","spec":"44.4 ml Light rum; 29.6 ml Pineapple juice; 2.5 ml Maraschino liqueur; 2.5 ml Grenadine; 1 Maraschino cherry","method":"Shake and strain into a chilled large cocktail glass","taste":"Rounded sweetness, tropical fruit. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Mary Pickford. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Mezcal Margarita","spirit":"mezcal","base":"Mezcal","family":"sour","spec":"50 ml mezcal; 25 ml orange liqueur; 25 ml lime juice; 5 ml agave syrup, optional","method":"Shake with ice; strain over fresh ice or serve up. Salt rim optional.","taste":"Agave, smoke or mineral character, orange and fresh lime; adjust sweetness to the bottle.","history":"A modern Margarita variation; no single inventor or first date is established.","glass":"Rocks / coupe","origin":"A modern Margarita variation; no single inventor or first date is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Michelada","spirit":"beer","base":"Beer","family":"sour","spec":"118.3 ml Beer; 118.3 ml Tomato Juice; 1 tblsp Lime Juice; Dash Hot Sauce; Dash Worcestershire Sauce; Dash Soy Sauce","method":"Mix the beer with tomato juice, freshly squeezed lime juice, and Worcestershire sauce, teriyaki sauce, soy sauce, or hot sauce.\r\nServed In a chilled, salt-rimmed glass","taste":"Bright citrus, rounded sweetness, lively bubbles. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Michelada. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Pint glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Mimosa","spirit":"wine","base":"Wine","family":"sparkling","spec":"75 ml chilled sparkling wine; 75 ml fresh orange juice","method":"Pour sparkling wine into a flute; add juice gently.","taste":"Citrusy, bright and softly sparkling.","history":"Popularized in Paris and London in the 1920s; the exact first hotel or bartender is debated.","glass":"Coupe / rocks","origin":"Historical note: Popularized in Paris and London in the 1920s; the exact first hotel or bartender is debated.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Mint Julep","spirit":"bourbon","base":"Bourbon","family":"spirit-forward","spec":"60 ml bourbon; 10 ml simple syrup; 8–10 mint leaves; crushed ice","method":"Gently press mint with syrup; add bourbon and crushed ice; churn until frosty. Mint bouquet garnish.","taste":"Cool mint aroma, sweet oak and bourbon warmth.","history":"A julep is an older family of spirit-and-mint drinks. The Kentucky bourbon version became closely associated with the Kentucky Derby in the 20th century.","glass":"Coupe / rocks","origin":"Historical note: A julep is an older family of spirit-and-mint drinks. The Kentucky bourbon version became closely associated with the Kentucky Derby in the 20th century.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Missionary's Downfall","spirit":"rum","base":"Rum","family":"tropical","spec":"30 ml light rum; 15 ml peach liqueur; 15 ml honey syrup; 15 ml lime juice; 60 ml pineapple juice; mint","method":"Shake with crushed ice; open-pour into a chilled tiki glass; mint garnish.","taste":"Pineapple and mint, soft peach, lime and rum; bright and lightly creamy if a little coconut is added.","history":"A Don the Beachcomber tiki recipe from the 1940s; versions vary and the original bar recipes were closely guarded.","glass":"Coupe / rocks","origin":"A Don the Beachcomber tiki recipe from the 1940s; versions vary and the original bar recipes were closely guarded.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Mojito","spirit":"rum","base":"Rum","family":"highball","spec":"50 ml white rum; 25 ml lime; 2 tsp sugar; mint; soda water","method":"Gently press mint with sugar and lime; add rum and ice; top with soda.","taste":"Fresh, minty, citrusy, lightly sweet and sparkling.","history":"A Cuban drink with antecedents in older rum-and-lime punches. The modern Mojito is associated with Havana; popular Hemingway claims are often overstated.","glass":"Coupe / rocks","origin":"Historical note: A Cuban drink with antecedents in older rum-and-lime punches. The modern Mojito is associated with Havana; popular Hemingway claims are often overstated.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Monkey Gland","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"59.1 ml Gin; 4.9 ml Benedictine; 14.8 ml Orange juice; 4.9 ml Grenadine","method":"Shake well over ice cubes in a shaker, strain into a chilled cocktail glass.","taste":"Orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Monkey Gland. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Moscow Mule","spirit":"vodka","base":"Vodka","family":"highball","spec":"45 ml vodka; 15 ml lime; 120 ml ginger beer","method":"Build over ice in a highball or mule mug; add lime and ginger beer; stir gently.","taste":"Zesty lime, peppery ginger, crisp and fizzy.","history":"Popularized in the United States in the 1940s. The copper mug is strongly associated with its marketing, not essential to the recipe.","glass":"Coupe / rocks","origin":"Historical note: Popularized in the United States in the 1940s. The copper mug is strongly associated with its marketing, not essential to the recipe.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Negroni","spirit":"gin","base":"Gin","family":"bitter aperitivo","spec":"30 ml gin; 30 ml bitter aperitivo; 30 ml sweet vermouth","method":"Build or stir over ice in a rocks glass; orange peel.","taste":"Bittersweet, herbal, citrus-oiled, full.","history":"Widely associated with Florence in the early 20th century and Count Camillo Negroni, who reportedly asked for a stronger Americano-style drink. The anecdote is not definitive proof.","glass":"Coupe / rocks","origin":"Historical note: Widely associated with Florence in the early 20th century and Count Camillo Negroni, who reportedly asked for a stronger Americano-style drink. The anecdote is not definitive proof.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"New York Sour","spirit":"whiskey","base":"Whiskey","family":"sour","spec":"60 ml bourbon or rye; 25 ml lemon juice; 20 ml simple syrup; 15 ml dry red wine float","method":"Shake whiskey, lemon and syrup with ice; strain over fresh ice in a rocks glass; float wine gently over the back of a spoon.","taste":"A whiskey sour’s sweet-tart grain core with a fruity, lightly tannic wine aroma and layered finish.","history":"A red-wine-topped whiskey sour is documented in 19th-century American drink culture, sometimes under other names. “New York Sour” became the familiar modern name; attribution varies.","glass":"Whiskey sour glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Old Fashioned","spirit":"whiskey","base":"Whiskey","family":"spirit-forward","spec":"60 ml bourbon or rye; 7.5 ml rich syrup; 2 dashes aromatic bitters","method":"Stir over ice; strain or build over a large cube. Express an orange peel.","taste":"Spirit-led, bittersweet, aromatic.","history":"An early 19th-century family of spirit, sugar, water and bitters drinks. The “old-fashioned” label became popular as drinkers asked for cocktails made the old way; exact first bartender is uncertain.","glass":"Coupe / rocks","origin":"Historical note: An early 19th-century family of spirit, sugar, water and bitters drinks. The “old-fashioned” label became popular as drinkers asked for cocktails made the old way; exact first bartender is uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Paloma","spirit":"tequila","base":"Tequila","family":"highball","spec":"50 ml blanco tequila; 15 ml lime; pinch of salt; 100 ml grapefruit soda","method":"Build over ice in a highball; top with grapefruit soda; gentle lift.","taste":"Bitter-sweet grapefruit, saline, agave, refreshingly fizzy.","history":"A beloved Mexican highball. Its name is often linked to the song “La Paloma,” but the exact origin remains unconfirmed.","glass":"Coupe / rocks","origin":"Historical note: A beloved Mexican highball. Its name is often linked to the song “La Paloma,” but the exact origin remains unconfirmed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Paper Plane","spirit":"bourbon","base":"Bourbon","family":"equal-parts sour","spec":"22.5 ml bourbon; 22.5 ml Aperol; 22.5 ml Amaro Nonino; 22.5 ml lemon juice","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Balanced bittersweet citrus, orange, amaro herbs and bourbon warmth.","history":"Created by Sam Ross in New York around 2007; named after the M.I.A. song popular at the time.","glass":"Coupe","origin":"Created by Sam Ross in New York around 2007; named after the M.I.A. song popular at the time.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Penicillin","spirit":"whiskey","base":"Whiskey","family":"modern classic","spec":"60 ml blended Scotch; 22.5 ml lemon; 22.5 ml honey-ginger syrup; 7.5 ml peated Scotch float","method":"Shake first three with ice; strain over ice; float peated Scotch.","taste":"Honeyed ginger, lemon, malt and smoky finish.","history":"Created by Sam Ross at New York’s Milk & Honey in the mid-2000s; a modern classic inspired by the Gold Rush template.","glass":"Coupe / rocks","origin":"Historical note: Created by Sam Ross at New York’s Milk & Honey in the mid-2000s; a modern classic inspired by the Gold Rush template.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Piña Colada","spirit":"rum","base":"Rum","family":"tropical","spec":"50 ml white or aged rum; 30 ml cream of coconut; 90 ml pineapple juice","method":"Shake or blend with crushed ice; garnish pineapple.","taste":"Creamy, tropical, sweet-tart, coconut-rich.","history":"Officially linked with Puerto Rico and San Juan, with competing mid-20th-century origin stories. It became Puerto Rico’s official drink in 1978.","glass":"Coupe / rocks","origin":"Historical note: Officially linked with Puerto Rico and San Juan, with competing mid-20th-century origin stories. It became Puerto Rico’s official drink in 1978.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Pisco Sour","spirit":"pisco","base":"Pisco","family":"sour","spec":"60 ml pisco; 30 ml lime juice; 20 ml simple syrup; 20 ml egg white; bitters","method":"Dry shake; shake with ice; strain into a chilled glass; dot bitters on foam.","taste":"Grape perfume, tart lime, silky foam.","history":"Peru’s Pisco Sour is commonly credited to Victor Vaughen Morris in Lima in the early 20th century; Chile has its own pisco sour tradition.","glass":"Coupe / rocks","origin":"Historical note: Peru’s Pisco Sour is commonly credited to Victor Vaughen Morris in Lima in the early 20th century; Chile has its own pisco sour tradition.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Planter's Punch","spirit":"rum","base":"Rum","family":"bitter aperitivo","spec":"45 ml Dark Rum; 30 ml Orange Juice; 35 ml Pineapple Juice; 10 ml Grenadine; 10 ml Sugar Syrup; 4 drops Angostura Bitters","method":"Squeeze an orange and strain the juice. Put all the ingredients in a shaker filled with ice and shake for at least 12 seconds. Strain into a highball glass and decorate with a pineapple wedge or fruit of your choice.","taste":"Orange peel, rounded sweetness, bitter-herbal structure, tropical fruit. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Planter's Punch. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Highball glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Porn Star Martini","spirit":"vodka","base":"Vodka","family":"modern sour","spec":"40 ml vanilla vodka; 20 ml passion-fruit liqueur; 30 ml passion-fruit purée; 15 ml lime; 10 ml vanilla syrup; sparkling wine on side","method":"Shake cocktail ingredients; strain into coupe; serve sparkling wine separately.","taste":"Perfumed tropical fruit, vanilla, tangy acidity.","history":"Created by Douglas Ankrah in London in the early 2000s. The serve is modern and widely adapted; prosecco on the side is customary in many versions.","glass":"Coupe / rocks","origin":"Historical note: Created by Douglas Ankrah in London in the early 2000s. The serve is modern and widely adapted; prosecco on the side is customary in many versions.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Ramos Gin Fizz","spirit":"gin","base":"Gin","family":"fizz","spec":"45 ml gin; 15 ml lemon; 15 ml lime; 30 ml syrup; 30 ml cream; egg white; orange flower water; soda","method":"Shake very thoroughly with ice; strain into chilled fizz glass; top soda.","taste":"Creamy, citrusy, floral and effervescent.","history":"Created by Henry C. Ramos in New Orleans in 1888. The legendary shaker-line stories are part of its lore, not a service requirement.","glass":"Coupe / rocks","origin":"Historical note: Created by Henry C. Ramos in New Orleans in 1888. The legendary shaker-line stories are part of its lore, not a service requirement.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Rob Roy","spirit":"scotch whisky","base":"Scotch whisky","family":"spirit-forward","spec":"60 ml blended Scotch whisky; 30 ml sweet vermouth; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; garnish with a cherry or lemon twist.","taste":"Malt, wine sweetness and spice; richer and often smokier than a Manhattan.","history":"Named for the operetta Rob Roy, which opened in New York in 1894; the drink appeared around that period.","glass":"Coupe","origin":"Named for the operetta Rob Roy, which opened in New York in 1894; the drink appeared around that period.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Rusty Nail","spirit":"whiskey","base":"Whiskey","family":"spirit-forward","spec":"45 ml Scotch whisky; 25 ml Drambuie","method":"Build over a large ice cube; stir gently; lemon twist optional.","taste":"Honeyed herbs, malt, warm spice.","history":"A Scotch-and-Drambuie combination that gained popularity in mid-20th-century cocktail culture; exact invention is unclear.","glass":"Coupe / rocks","origin":"Historical note: A Scotch-and-Drambuie combination that gained popularity in mid-20th-century cocktail culture; exact invention is unclear.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Sazerac","spirit":"rye","base":"Rye","family":"spirit-forward","spec":"60 ml rye whiskey; 1 sugar cube; 3 dashes Peychaud’s bitters; absinthe rinse","method":"Stir whiskey, sugar and bitters with ice; rinse chilled glass with absinthe; strain.","taste":"Anise perfume, rye spice, dry bitters and citrus oil.","history":"A New Orleans classic associated with the Sazerac brandy/rye tradition and 19th-century apothecary Antoine Peychaud. Its exact origin narrative is layered.","glass":"Coupe / rocks","origin":"Historical note: A New Orleans classic associated with the Sazerac brandy/rye tradition and 19th-century apothecary Antoine Peychaud. Its exact origin narrative is layered.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Sea Breeze","spirit":"vodka","base":"Vodka","family":"sour","spec":"44.4 ml Vodka; 118.3 ml Cranberry juice; 29.6 ml Grapefruit juice","method":"Build all ingredients in a highball glass filled with ice. Garnish with lime wedge.","taste":"Bright citrus, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Sea Breeze. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Highball glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Sidecar","spirit":"brandy","base":"Brandy","family":"sour","spec":"50 ml Cognac; 20 ml orange liqueur; 20 ml lemon juice","method":"Shake with ice; strain into a chilled coupe; optional fine sugar rim.","taste":"Dry citrus, orange, warming grape spirit.","history":"A post–World War I classic with competing Paris and London origin stories; published recipes appear by the 1920s.","glass":"Coupe / rocks","origin":"Historical note: A post–World War I classic with competing Paris and London origin stories; published recipes appear by the 1920s.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Singapore Sling","spirit":"gin","base":"Gin","family":"tropical","spec":"30 ml gin; 15 ml cherry liqueur; 7.5 ml orange liqueur; 7.5 ml Bénédictine; 10 ml grenadine; 15 ml lime; 120 ml pineapple juice; bitters","method":"Shake with ice; strain into an ice-filled tall glass; garnish pineapple and cherry.","taste":"Long, fruity, spiced and lightly bitter.","history":"Associated with Ngiam Tong Boon at Singapore’s Raffles Hotel in the early 20th century; recipes changed substantially over time.","glass":"Coupe / rocks","origin":"Historical note: Associated with Ngiam Tong Boon at Singapore’s Raffles Hotel in the early 20th century; recipes changed substantially over time.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Southside","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 25 ml lime juice; 20 ml simple syrup; 6 mint leaves; 1 dash aromatic bitters, optional","method":"Shake all with ice; double-strain into a chilled coupe; mint garnish.","taste":"Mint, citrus and juniper; clean, fragrant and gently sweet.","history":"A pre-Prohibition gin-and-mint sour associated with Chicago and New York; multiple origin stories remain unproven.","glass":"Coupe","origin":"A pre-Prohibition gin-and-mint sour associated with Chicago and New York; multiple origin stories remain unproven.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Spritz Veneziano","spirit":"wine","base":"Wine","family":"highball","spec":"60 ml Prosecco; 40 ml Aperol; Top Soda Water","method":"Build into glass over ice, garnish and serve.","taste":"Bitter-herbal structure, lively bubbles. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Spritz Veneziano. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Wine Glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Tom Collins","spirit":"gin","base":"Gin","family":"highball","spec":"45 ml gin; 30 ml lemon; 15 ml simple syrup; 60–90 ml soda water","method":"Shake gin, lemon and syrup; strain over ice into a Collins glass; top with soda.","taste":"Bright, lightly sweet, sparkling and botanical.","history":"A 19th-century gin punch/highball family. The Tom Collins name is documented in 1870s bartending literature; exact naming lore is contested.","glass":"Coupe / rocks","origin":"Historical note: A 19th-century gin punch/highball family. The Tom Collins name is documented in 1870s bartending literature; exact naming lore is contested.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Tommy's Margarita","spirit":"blanco tequila","base":"Blanco tequila","family":"sour","spec":"60 ml 100% agave blanco tequila; 30 ml lime juice; 15 ml agave nectar diluted 1:1","method":"Shake with ice; strain over fresh ice in a rocks glass. Salt rim optional.","taste":"Agave-forward, bright lime and rounded agave sweetness without orange liqueur.","history":"Created by Julio Bermejo at Tommy’s Mexican Restaurant in San Francisco in the early 1990s.","glass":"Rocks","origin":"Created by Julio Bermejo at Tommy’s Mexican Restaurant in San Francisco in the early 1990s.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Trinidad Sour","spirit":"rye whiskey","base":"Rye whiskey","family":"equal-parts sour","spec":"45 ml rye whiskey; 22.5 ml Angostura bitters; 30 ml lemon juice; 15 ml orgeat","method":"Shake hard with ice; fine-strain into a chilled coupe.","taste":"Aromatic spice and almond, surprisingly tart and complex; bitters are a principal ingredient.","history":"Created by Giuseppe Gonzalez at Clover Club, Brooklyn, in the mid-2000s; it made Angostura bitters a starring ingredient.","glass":"Coupe","origin":"Created by Giuseppe Gonzalez at Clover Club, Brooklyn, in the mid-2000s; it made Angostura bitters a starring ingredient.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Vesper","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"45 ml gin; 15 ml vodka; 7.5 ml Lillet Blanc or another dry aperitif wine","method":"Shake very cold with ice; strain into a chilled cocktail glass; express a large lemon peel.","taste":"Very dry, high-proof and citrus-aromatic; the fortified-wine component rounds the spirit blend.","history":"The Vesper was created as a fictional drink in Ian Fleming’s 1953 novel Casino Royale and named for Vesper Lynd. The original literary specification used Kina Lillet, a historic formulation no longer sold unchanged.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Vieux Carré","spirit":"whiskey","base":"Whiskey","family":"spirit-forward","spec":"30 ml rye; 30 ml cognac; 30 ml sweet vermouth; 1 tsp Bénédictine; bitters","method":"Stir with ice; strain over a large cube; lemon twist.","taste":"Layered, herbal, bittersweet, richly aromatic.","history":"Created at the Hotel Monteleone’s Carousel Bar in New Orleans in the 1930s; named for the French Quarter.","glass":"Coupe / rocks","origin":"Historical note: Created at the Hotel Monteleone’s Carousel Bar in New Orleans in the 1930s; named for the French Quarter.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Whiskey Sour","spirit":"whiskey","base":"Whiskey","family":"sour","spec":"60 ml bourbon; 25 ml lemon juice; 20 ml simple syrup; optional egg white","method":"Shake (dry shake first if using egg); shake with ice; strain.","taste":"Citrus-bright, rounded, whiskey warmth.","history":"Sours appear in 19th-century bartending literature. The whiskey version is a classic formula rather than a securely attributable single invention.","glass":"Coupe / rocks","origin":"Historical note: Sours appear in 19th-century bartending literature. The whiskey version is a classic formula rather than a securely attributable single invention.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"White Lady","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 30 ml orange liqueur; 20 ml lemon juice; optional egg white","method":"Shake with ice; fine-strain into chilled coupe.","taste":"Crisp citrus, orange perfume and dry gin.","history":"A 1920s-era drink with versions by Harry MacElhone and Harry Craddock; the proportions evolved over time.","glass":"Coupe / rocks","origin":"Historical note: A 1920s-era drink with versions by Harry MacElhone and Harry Craddock; the proportions evolved over time.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Zombie","spirit":"rum","base":"Rum","family":"sour","spec":"44.4 ml Rum; 44.4 ml Gold rum; 29.6 ml 151 proof rum; 4.9 ml Pernod; 4.9 ml Grenadine; 4.9 ml Lime Juice; 1 drop Angostura Bitters","method":"Blend at high speed for no more than 5 seconds.\n\nPour into a glass, add ice cubes to fill, then add the garnish.\n\n*Donn’s mix: Bring 3 crushed cinnamon sticks, 1 cup of sugar and 1 cup of water to a boil, stirring until the sugar is dissolved.\n\nSimmer for 2 minutes, then remove from the heat and let sit for at least 2 hours before straining into a clean glass bottle.\n\nThen add 1 part of the syrup and 2 parts of fresh grapefruit juice together.","taste":"Bright citrus, rounded sweetness, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Zombie. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Hurricane glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Adonis","spirit":"fino sherry","base":"Fino sherry","family":"spirit-forward","spec":"45 ml fino or amontillado sherry; 45 ml sweet vermouth; 2 dashes orange bitters","method":"Stir with ice; strain into a chilled coupe; orange twist.","taste":"Low-ABV, savory, nutty, wine-led and gently bitter.","history":"Named for the 1880s Broadway musical Adonis; it is one of the early low-alcohol vermouth cocktails.","glass":"Coupe","origin":"Named for the 1880s Broadway musical Adonis; it is one of the early low-alcohol vermouth cocktails.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Alexander","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"14.8 ml Gin; 1/2 oz white Creme de Cacao; 59.1 ml Light cream; to taste Nutmeg","method":"Shake all ingredients with ice and strain contents into a cocktail glass. Sprinkle nutmeg on top and serve.","taste":"Rounded sweetness, soft, creamy texture. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Alexander. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Angel Face","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"14.8 ml Apricot brandy; 14.8 ml Apple brandy; 29.6 ml Gin","method":"Shake all ingredients with ice and strain contents into a cocktail glass.","taste":"Spirit-led warmth, a measured sweet-bitter balance. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Angel Face. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Army & Navy","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 25 ml lemon juice; 20 ml orgeat; 1 dash aromatic bitters","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Juniper and lemon with soft almond sweetness and a faint spice note.","history":"A mid-20th-century American gin sour found in David Embury’s 1948 book; the naming reference is commonly linked to the Army–Navy football game.","glass":"Coupe","origin":"A mid-20th-century American gin sour found in David Embury’s 1948 book; the naming reference is commonly linked to the Army–Navy football game.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bamboo","spirit":"fino sherry","base":"Fino sherry","family":"spirit-forward","spec":"45 ml dry sherry; 45 ml dry vermouth; 1 dash orange bitters; 1 dash aromatic bitters","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Dry, savory, gently saline and aromatic; a low-ABV aperitif.","history":"A late-19th-century drink associated with Louis Eppinger in Yokohama, Japan; its early recipes varied.","glass":"Coupe","origin":"A late-19th-century drink associated with Louis Eppinger in Yokohama, Japan; its early recipes varied.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bobby Burns","spirit":"scotch whisky","base":"Scotch whisky","family":"spirit-forward","spec":"45 ml Scotch whisky; 30 ml sweet vermouth; 7.5 ml Bénédictine; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Malt, vermouth spice and herbal honey with a long finish.","history":"A Scotch-and-vermouth drink documented in early 20th-century cocktail books and named for Scottish poet Robert Burns; recipes vary.","glass":"Coupe","origin":"A Scotch-and-vermouth drink documented in early 20th-century cocktail books and named for Scottish poet Robert Burns; recipes vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Brooklyn","spirit":"whiskey","base":"Whiskey","family":"bitter aperitivo","spec":"59.1 ml Rye Whiskey; 29.6 ml Dry Vermouth; 7.4 ml Maraschino Liqueur; 3 dashes Angostura Bitters; 1 Maraschino Cherry","method":"Combine ingredients with ice and stir until well-chilled. Strain into a chilled cocktail glass.","taste":"Rounded sweetness, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Brooklyn. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Canchánchara","spirit":"cuban aguardiente","base":"Cuban aguardiente","family":"sour","spec":"60 ml Cuban aguardiente or unaged rum; 20 ml lime juice; 20 ml honey syrup; 15 ml water","method":"Stir or shake briefly; serve over ice in a small rocks glass; lime wedge.","taste":"Cane spirit, honey and lively lime; rustic and refreshing.","history":"A Cuban drink linked to the independence-era town of Trinidad. Exact origin dating is part of local tradition rather than firm documentation.","glass":"Rocks","origin":"A Cuban drink linked to the independence-era town of Trinidad. Exact origin dating is part of local tradition rather than firm documentation.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Champagne Julep","spirit":"cognac","base":"Cognac","family":"sparkling","spec":"45 ml Cognac; 10 ml simple syrup; 6 mint leaves; 60 ml chilled sparkling wine","method":"Gently press mint with syrup; add Cognac and crushed ice; churn; top gently with sparkling wine.","taste":"Mint, grape spirit and dry bubbles; aromatic and celebratory.","history":"A julep-family variation appearing in historic cocktail writing; exact first creator and standard proportions are uncertain.","glass":"Coupe / rocks","origin":"A julep-family variation appearing in historic cocktail writing; exact first creator and standard proportions are uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Chartreuse Swizzle","spirit":"green chartreuse","base":"Green Chartreuse","family":"tropical","spec":"45 ml green Chartreuse; 30 ml pineapple juice; 22.5 ml lime juice; 15 ml falernum","method":"Build in a tall glass with crushed ice; swizzle until frosty; mint garnish.","taste":"Intensely herbal, citrusy, tropical and gently spiced.","history":"Created by Marco Dionysos at San Francisco’s Harry Denton’s Starlight Room in the early 2000s.","glass":"Highball","origin":"Created by Marco Dionysos at San Francisco’s Harry Denton’s Starlight Room in the early 2000s.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Cobra's Fang","spirit":"jamaican rum","base":"Jamaican rum","family":"tropical","spec":"45 ml Jamaican rum; 15 ml overproof rum; 15 ml lime juice; 15 ml orange juice; 15 ml passion-fruit syrup; 7.5 ml falernum; 7.5 ml grenadine; 2 dashes aromatic bitters","method":"Shake with crushed ice; pour into a tall tiki glass; garnish mint and citrus.","taste":"Funky cane, passion fruit, citrus and layered spice; intense and tropical.","history":"A Don the Beachcomber-era tiki drink; historical formulas vary and are not always fully recoverable.","glass":"Coupe / rocks","origin":"A Don the Beachcomber-era tiki drink; historical formulas vary and are not always fully recoverable.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Colombia","spirit":"aguardiente","base":"Aguardiente","family":"sour","spec":"45 ml aguardiente; 25 ml lime juice; 15 ml panela syrup; 30 ml pineapple juice","method":"Shake with ice; strain over fresh ice; garnish lime.","taste":"Anise-like cane spirit, tropical fruit and bright lime.","history":"The name is used for multiple modern regional drinks; a single canonical first-creation record is not established.","glass":"Coupe / rocks","origin":"The name is used for multiple modern regional drinks; a single canonical first-creation record is not established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Corn 'n' Oil","spirit":"rum","base":"Rum","family":"bitter aperitivo","spec":"1/2 Lime; 9.9 ml Falernum; 2 dashes Angostura Bitters; 29.6 ml Añejo rum; 29.6 ml blackstrap rum","method":"Cut the half lime in half again. Add the lime, falernum, and bitters to a rocks glass. Muddle. Add the rum. (Aged Barbados rum such as Plantation 5 Year is recommended). Add ice and stir. Float the blackstrap rum on top. Serve with a straw.","taste":"Bright citrus, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Corn 'n' Oil. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Old-fashioned glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Daisy","spirit":"brandy","base":"Brandy","family":"daisy","spec":"60 ml brandy; 20 ml lemon juice; 15 ml orange liqueur; 10 ml simple syrup; 30 ml soda water","method":"Shake brandy, lemon, liqueur and syrup with ice; strain over fresh ice; top soda.","taste":"Brandy fruit, citrus and orange sweetness with a sparkling finish.","history":"A 19th-century cocktail family; spirit, liqueur and citrus combinations changed across editions and venues.","glass":"Coupe / rocks","origin":"A 19th-century cocktail family; spirit, liqueur and citrus combinations changed across editions and venues.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Death in the Afternoon","spirit":"wine","base":"Wine","family":"highball","spec":"15 ml absinthe; 90 ml chilled Champagne or dry sparkling wine","method":"Pour absinthe into a chilled coupe; slowly add sparkling wine. Serve a small measured portion and sip slowly.","taste":"Anise and herbal intensity meet dry, brisk bubbles; aromatic, lean and potent for its size.","history":"The name is associated with Ernest Hemingway and the 1935 collection of the same name, which printed a brief absinthe-and-Champagne recipe. Keep the historical literary association distinct from later serving lore.","glass":"Margarita glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Derby","spirit":"gin","base":"Gin","family":"bitter aperitivo","spec":"60 ml gin; 2 dashes Peach Bitters; 2 Fresh leaves Mint","method":"Pour all ingredients into a mixing glass with ice. Stir. Strain into a cocktail glass. Garnish with a sprig of fresh mint in the drink.","taste":"Bitter-herbal structure, herbal aroma. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Derby. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Diki-Diki","spirit":"calvados","base":"Calvados","family":"sour","spec":"45 ml Calvados; 30 ml Swedish punsch; 15 ml grapefruit juice; 10 ml lemon juice","method":"Shake with ice; strain into a chilled coupe.","taste":"Apple brandy, tea-like punsch and bitter citrus; dry-fruited and aromatic.","history":"A pre-Prohibition recipe appearing in classic cocktail books; the origin story and exact original proportions are uncertain.","glass":"Coupe / rocks","origin":"A pre-Prohibition recipe appearing in classic cocktail books; the origin story and exact original proportions are uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Division Bell","spirit":"mezcal","base":"Mezcal","family":"equal-parts sour","spec":"22.5 ml mezcal; 22.5 ml Aperol; 22.5 ml maraschino liqueur; 22.5 ml lime juice","method":"Shake with ice; fine-strain into a chilled coupe; lime wheel.","taste":"Smoky or mineral agave, bitter orange, tart lime and maraschino.","history":"Created by Phil Ward at Mayahuel, New York, in the late 2000s; named after a Pink Floyd album.","glass":"Coupe","origin":"Created by Phil Ward at Mayahuel, New York, in the late 2000s; named after a Pink Floyd album.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Eastside","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 25 ml lime juice; 20 ml simple syrup; cucumber; mint","method":"Muddle cucumber and mint lightly; shake all ingredients with ice; double-strain into a chilled coupe.","taste":"Cool cucumber, mint and lime over a crisp botanical base.","history":"A modern gin sour variant associated with New York cocktail bars; attribution varies by recipe and venue.","glass":"Coupe","origin":"A modern gin sour variant associated with New York cocktail bars; attribution varies by recipe and venue.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Enzoni","spirit":"gin","base":"Gin","family":"sour","spec":"30 ml gin; 30 ml Campari; 22.5 ml lemon juice; 15 ml simple syrup; 5 green grapes","method":"Muddle grapes gently; shake all ingredients with ice; double-strain over fresh ice.","taste":"Grape fruitiness, citrus and assertive bitter orange with botanical gin.","history":"Created by Vincenzo Errico at Milk & Honey in New York in the early 2000s.","glass":"Rocks","origin":"Created by Vincenzo Errico at Milk & Honey in New York in the early 2000s.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Espresso Tonic","spirit":"gin","base":"Gin","family":"highball","spec":"30 ml gin; 30 ml chilled espresso; 120 ml tonic water","method":"Build tonic over ice; add gin; slowly float cooled espresso; garnish orange peel.","taste":"Roast coffee, bitter quinine and botanical gin; crisp, aromatic and lightly sparkling.","history":"A modern coffee-bar highball with multiple independent origins; no single inventor is firmly established.","glass":"Coupe / rocks","origin":"A modern coffee-bar highball with multiple independent origins; no single inventor is firmly established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Eternal Sunshine","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 20 ml elderflower liqueur; 20 ml grapefruit juice; 15 ml lime juice; 10 ml simple syrup","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Floral elderflower, grapefruit bitterness and fresh lime over botanicals.","history":"The name is used by modern house recipes; no reliable first-creation date or location is established.","glass":"Coupe / rocks","origin":"The name is used by modern house recipes; no reliable first-creation date or location is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Fair Harvard","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"60 ml rye whiskey; 20 ml sweet vermouth; 10 ml dry vermouth; 5 ml grenadine; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Rye spice, balanced wine, bitters and a light pomegranate note.","history":"A historical American cocktail name found in early 20th-century recipe collections; exact attribution and canonical spec are uncertain.","glass":"Coupe / rocks","origin":"A historical American cocktail name found in early 20th-century recipe collections; exact attribution and canonical spec are uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Fitzgerald","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 22.5 ml lemon juice; 15 ml simple syrup; 2 dashes Angostura bitters","method":"Shake with ice; strain over fresh ice or into a coupe; lemon twist.","taste":"Classic gin sour structure with aromatic spice and a dry finish.","history":"A modern gin sour associated with Dale DeGroff and New York bar culture; details of naming and first service vary.","glass":"Rocks / coupe","origin":"A modern gin sour associated with Dale DeGroff and New York bar culture; details of naming and first service vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Fog Cutter","spirit":"rum","base":"Rum","family":"tropical","spec":"30 ml white rum; 30 ml gin; 30 ml brandy; 45 ml lemon juice; 30 ml orange juice; 15 ml orgeat; 15 ml fino sherry float","method":"Shake everything except sherry with ice; pour into a tall glass over crushed ice; float sherry.","taste":"Layered spirits, citrus and almond, with a dry sherry finish.","history":"A tiki drink credited to Victor Bergeron (Trader Vic) in the 1940s; several published versions exist.","glass":"Highball / tiki","origin":"A tiki drink credited to Victor Bergeron (Trader Vic) in the 1940s; several published versions exist.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Garibaldi","spirit":"campari","base":"Campari","family":"bitter aperitivo","spec":"45 ml Campari; 120 ml fresh orange juice","method":"Build over ice in a highball; stir gently; orange slice.","taste":"Bitter orange and juicy citrus; fluffy fresh juice softens the aperitivo.","history":"Named for Italian unification leader Giuseppe Garibaldi; the orange-red colors echo the red-shirted volunteers. Exact invention details are uncertain.","glass":"Highball","origin":"Named for Italian unification leader Giuseppe Garibaldi; the orange-red colors echo the red-shirted volunteers. Exact invention details are uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Gin-Gin Mule","spirit":"gin","base":"Gin","family":"highball","spec":"45 ml gin; 22.5 ml lime juice; 15 ml simple syrup; mint; 90 ml ginger beer","method":"Muddle mint gently with syrup; shake gin and lime with ice; strain over ice and top with ginger beer.","taste":"Mint, lime, juniper and gingery spice; a bright, aromatic highball.","history":"Created by Audrey Saunders at Pegu Club, New York, in the early 2000s.","glass":"Highball","origin":"Created by Audrey Saunders at Pegu Club, New York, in the early 2000s.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Golden Dream","spirit":"vodka","base":"Vodka","family":"sour","spec":"30 ml Galliano; 30 ml orange liqueur; 30 ml orange juice; 15 ml cream","method":"Shake with ice; strain into chilled cocktail glass.","taste":"Creamy orange, vanilla and herbal sweetness.","history":"A mid-20th-century cocktail later recognized by the IBA; attribution varies across sources.","glass":"Coupe / rocks","origin":"Historical note: A mid-20th-century cocktail later recognized by the IBA; attribution varies across sources.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Grasshopper","spirit":"spirit","base":"Spirit","family":"spirit-forward","spec":"22.2 ml Green Creme de Menthe; 3/4 oz white Creme de Cacao; 22.2 ml Light cream","method":"Pour ingredients into a cocktail shaker with ice. Shake briskly and then strain into a chilled cocktail glass.","taste":"Rounded sweetness, soft, creamy texture. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Grasshopper. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Greyhound","spirit":"vodka","base":"Vodka","family":"sour","spec":"44.4 ml Vodka; 88.7 ml Grapefruit Juice","method":"Add the vodka to a Collins glass filled with ice.\nTop with grapefruit juice and stir.","taste":"Bright citrus, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Greyhound. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Collins glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Horses Neck","spirit":"gin","base":"Gin","family":"bitter aperitivo","spec":"1 long strip Lemon peel; 59.1 ml Brandy; 147.9 ml Ginger ale; 2 dashes Bitters","method":"Pour brandy and ginger ale directly into highball glass with ice cubes. Stir gently. Garnish with lemon zest. If desired, add dashes of Angostura Bitter.","taste":"Bright citrus, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Horses Neck. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Highball glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Improved Whiskey Cocktail","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"60 ml rye whiskey; 7.5 ml simple syrup; 2 dashes aromatic bitters; 5 ml maraschino liqueur; absinthe rinse","method":"Rinse a chilled rocks glass with absinthe. Stir remaining ingredients with ice; strain over a large cube.","taste":"Rye spice, bitters, cherry and aromatic anise.","history":"A 19th-century “improved” cocktail variant recorded in Jerry Thomas-era bartending literature; individual recipes varied.","glass":"Rocks","origin":"A 19th-century “improved” cocktail variant recorded in Jerry Thomas-era bartending literature; individual recipes varied.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Irish Coffee","spirit":"whiskey","base":"Whiskey","family":"hot drink","spec":"40 ml Irish whiskey; 120 ml hot coffee; 1–2 tsp sugar; lightly whipped cream","method":"Dissolve sugar in hot coffee and whiskey; float cream over the back of a spoon.","taste":"Bitter coffee, whiskey warmth, cool creamy top.","history":"Associated with Foynes, Ireland, in the 1940s and chef Joe Sheridan; later popularized in San Francisco by Stanton Delaplane.","glass":"Coupe / rocks","origin":"Historical note: Associated with Foynes, Ireland, in the 1940s and chef Joe Sheridan; later popularized in San Francisco by Stanton Delaplane.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Jack Rose","spirit":"applejack","base":"Applejack","family":"sour","spec":"60 ml applejack; 22.5 ml lemon juice; 15 ml grenadine","method":"Shake with ice; fine-strain into a chilled coupe; lemon twist.","taste":"Orchard fruit, tart citrus and pomegranate sweetness.","history":"An American cocktail documented in the early 20th century; competing stories link the name to a gambler or the pink color.","glass":"Coupe","origin":"An American cocktail documented in the early 20th century; competing stories link the name to a gambler or the pink color.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Japanese Cocktail","spirit":"cognac","base":"Cognac","family":"spirit-forward","spec":"60 ml Cognac; 15 ml orgeat; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; express lemon peel.","taste":"Grape spirit, almond and warm bitters; silky and aromatic.","history":"Published by Jerry Thomas in 1862 and named in connection with a Japanese diplomatic mission in New York; historical details are documented in period accounts.","glass":"Coupe","origin":"Published by Jerry Thomas in 1862 and named in connection with a Japanese diplomatic mission in New York; historical details are documented in period accounts.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"John Collins","spirit":"whiskey","base":"Whiskey","family":"sour","spec":"59.1 ml Bourbon; 29.6 ml Lemon juice; 1 tsp superfine Sugar; 88.7 ml Club soda; 1 Maraschino cherry; 1 Orange","method":"Pour all ingredients directly into highball glass filled with ice. Stir gently. Garnish. Add a dash of Angostura bitters.","taste":"Bright citrus, orange peel, rounded sweetness, lively bubbles. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for John Collins. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Collins glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Jasmine","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 15 ml Campari; 15 ml triple sec; 15 ml lemon juice","method":"Shake with ice; fine-strain into a chilled coupe; lemon twist.","taste":"Pink citrus, juniper and a subtle bitter-orange finish.","history":"Created by Paul Harrington in the 1990s; the recipe appeared in his cocktail writing and became a modern classic.","glass":"Coupe","origin":"Created by Paul Harrington in the 1990s; the recipe appeared in his cocktail writing and became a modern classic.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Kamikaze","spirit":"vodka","base":"Vodka","family":"sour","spec":"29.6 ml Vodka; 29.6 ml Triple sec; 29.6 ml Lime juice","method":"Shake all ingredients together with ice. Strain into glass, garnish and serve.","taste":"Bright citrus, orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Kamikaze. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Kentucky Mule","spirit":"bourbon","base":"Bourbon","family":"highball","spec":"60 ml bourbon; 15 ml lime juice; 120 ml ginger beer","method":"Build over ice in a highball or mule mug; stir gently; lime garnish.","taste":"Bourbon oak with lime and spicy ginger; crisp and refreshing.","history":"A regional whiskey variation on the Moscow Mule; no single inventor or first date is established.","glass":"Highball / mule mug","origin":"A regional whiskey variation on the Moscow Mule; no single inventor or first date is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"La Rosita","spirit":"tequila","base":"Tequila","family":"bitter aperitivo","spec":"45 ml reposado tequila; 15 ml sweet vermouth; 15 ml dry vermouth; 15 ml Campari; 1 dash Angostura bitters","method":"Stir with ice; strain into a chilled coupe; orange twist.","taste":"Agave, red-fruit wine, bitter herbs and oak spice.","history":"A modern tequila variation of the Negroni/Manhattan family, published by Gary Regan in the 1990s; attribution is commonly reported.","glass":"Coupe","origin":"A modern tequila variation of the Negroni/Manhattan family, published by Gary Regan in the 1990s; attribution is commonly reported.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Lumière","spirit":"gin","base":"Gin","family":"sparkling","spec":"30 ml gin; 15 ml elderflower liqueur; 15 ml lemon juice; 60 ml dry sparkling wine","method":"Shake gin, liqueur and lemon with ice; strain into a flute; top with sparkling wine.","taste":"Floral citrus and clean botanicals lifted by bubbles.","history":"A name shared by contemporary recipes; no single authoritative origin is asserted.","glass":"Coupe / rocks","origin":"A name shared by contemporary recipes; no single authoritative origin is asserted.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Lynchburg Lemonade","spirit":"tennessee whiskey","base":"Tennessee whiskey","family":"highball","spec":"45 ml Tennessee whiskey; 20 ml orange liqueur; 20 ml lemon juice; 90 ml lemon-lime soda","method":"Shake whiskey, orange liqueur and lemon with ice; strain over ice; top with soda.","taste":"Lemon, orange and whiskey, long and lightly sweet.","history":"Associated with Jack Daniel’s promotional history and a 1980s lawsuit involving Alabama bartender Tony Mason; the naming story is contested.","glass":"Highball","origin":"Associated with Jack Daniel’s promotional history and a 1980s lawsuit involving Alabama bartender Tony Mason; the naming story is contested.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Man O' War","spirit":"bourbon","base":"Bourbon","family":"sour","spec":"45 ml bourbon; 15 ml orange liqueur; 15 ml sweet vermouth; 15 ml lemon juice","method":"Shake with ice; strain into a chilled coupe; lemon twist.","taste":"Bourbon, orange, wine spice and bright lemon.","history":"Named for the famous racehorse and documented in mid-20th-century American cocktail books; precise first creator is uncertain.","glass":"Coupe","origin":"Named for the famous racehorse and documented in mid-20th-century American cocktail books; precise first creator is uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Manhattan Perfect","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"60 ml rye whiskey; 15 ml sweet vermouth; 15 ml dry vermouth; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; cherry or lemon twist.","taste":"Rye spice, balanced dry and sweet wine, aromatic bitters.","history":"A Manhattan variation that balances sweet and dry vermouth; no single inventor or date is documented.","glass":"Coupe","origin":"A Manhattan variation that balances sweet and dry vermouth; no single inventor or date is documented.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Margarita de Pomegranate","spirit":"tequila","base":"Tequila","family":"sour","spec":"50 ml blanco tequila; 20 ml orange liqueur; 20 ml lime juice; 20 ml pomegranate juice; 5 ml agave syrup","method":"Shake with ice; strain over fresh ice; lime garnish.","taste":"Agave, tart pomegranate, orange and fresh lime.","history":"A contemporary fruit Margarita variation; no unique creator or first date is reliably established.","glass":"Coupe / rocks","origin":"A contemporary fruit Margarita variation; no unique creator or first date is reliably established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Melon Ball","spirit":"vodka","base":"Vodka","family":"tropical","spec":"30 ml vodka; 30 ml melon liqueur; 60 ml orange juice","method":"Shake with ice; strain over fresh ice; garnish melon or orange.","taste":"Juicy melon and orange with a clean vodka base; sweet and fruit-led.","history":"A late-20th-century American party cocktail; exact origin is not reliably documented.","glass":"Highball","origin":"A late-20th-century American party cocktail; exact origin is not reliably documented.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Midori Sour","spirit":"melon liqueur","base":"Melon liqueur","family":"sour","spec":"45 ml melon liqueur; 30 ml lemon juice; 15 ml lime juice; 15 ml simple syrup; soda splash optional","method":"Shake with ice; strain over fresh ice; top lightly with soda if desired.","taste":"Sweet melon balanced by lively citrus; vivid and fruit-forward.","history":"Popularized in the United States after Midori’s 1978 launch; modern recipes vary considerably.","glass":"Rocks / highball","origin":"Popularized in the United States after Midori’s 1978 launch; modern recipes vary considerably.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Naked and Famous","spirit":"mezcal","base":"Mezcal","family":"equal-parts sour","spec":"22.5 ml mezcal; 22.5 ml yellow Chartreuse; 22.5 ml Aperol; 22.5 ml lime juice","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Smoke or mineral agave, citrus, bitter orange and herbal sweetness.","history":"Created by Joaquín Simó at Death & Co., New York, in 2011; a modern equal-parts riff on the Last Word.","glass":"Coupe","origin":"Created by Joaquín Simó at Death & Co., New York, in 2011; a modern equal-parts riff on the Last Word.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Navy Grog","spirit":"rum","base":"Rum","family":"tropical","spec":"30 ml white rum; 30 ml aged rum; 30 ml overproof rum; 22.5 ml lime juice; 22.5 ml grapefruit juice; 15 ml honey syrup","method":"Shake with crushed ice; pour into a rocks glass; garnish mint. Use overproof rum with care.","taste":"Layered cane, grapefruit, lime and honey; assertive and tropical.","history":"A Don the Beachcomber tiki classic from the 1940s; published recipes were often closely guarded and later versions vary.","glass":"Rocks / tiki","origin":"A Don the Beachcomber tiki classic from the 1940s; published recipes were often closely guarded and later versions vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"New York Cocktail","spirit":"rye whiskey","base":"Rye whiskey","family":"sour","spec":"60 ml rye whiskey; 20 ml lemon juice; 15 ml grenadine; 5 ml port wine float","method":"Shake rye, lemon and grenadine with ice; strain into a chilled coupe; float port carefully.","taste":"Rye, citrus and pomegranate with a vinous, lightly tannic finish.","history":"The name has been used for multiple historic formulas; this is one classic-style interpretation and not a single undisputed original.","glass":"Coupe / rocks","origin":"The name has been used for multiple historic formulas; this is one classic-style interpretation and not a single undisputed original.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Nixon","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"45 ml gin; 20 ml dry vermouth; 10 ml orange liqueur; 2 dashes orange bitters","method":"Stir with ice; strain into a chilled coupe; express orange peel.","taste":"Dry botanical gin, citrus oil and a light sweet-bitter edge.","history":"Several modern drinks use this name; a verified historical origin and canonical recipe are not established.","glass":"Coupe / rocks","origin":"Several modern drinks use this name; a verified historical origin and canonical recipe are not established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Old Pal","spirit":"whiskey","base":"Whiskey","family":"bitter aperitivo","spec":"45 ml rye whiskey; 30 ml bitter aperitivo; 30 ml dry vermouth","method":"Stir with ice until cold; strain into a chilled coupe or over a large cube; lemon twist.","taste":"Dry, bitter and spicy; rye’s pepper and dry vermouth make it leaner than a Boulevardier.","history":"The Old Pal is associated with Harry MacElhone’s 1920s Paris bar-writing and the journalist William “Sparrow” Robinson. The naming anecdote is repeated in later accounts, not definitive proof.","glass":"Nick and Nora Glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Orange Blossom","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 45 ml fresh orange juice; 5 ml simple syrup; 5 ml dry vermouth, optional","method":"Shake with ice; strain into a chilled coupe; orange twist.","taste":"Fresh orange, juniper and a lightly sweet citrus finish.","history":"A gin-and-orange family documented in early 20th-century cocktail books; recipes range from simple to vermouth-accented.","glass":"Coupe / rocks","origin":"A gin-and-orange family documented in early 20th-century cocktail books; recipes range from simple to vermouth-accented.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Painkiller","spirit":"rum","base":"Rum","family":"tropical","spec":"60 ml dark rum; 120 ml pineapple juice; 30 ml orange juice; 30 ml cream of coconut","method":"Shake with ice; pour over crushed ice; grate nutmeg and garnish pineapple.","taste":"Creamy coconut, pineapple, orange and warming rum.","history":"Associated with the Soggy Dollar Bar in the British Virgin Islands in the 1970s; the name is also a trademark in some markets.","glass":"Highball / tiki","origin":"Associated with the Soggy Dollar Bar in the British Virgin Islands in the 1970s; the name is also a trademark in some markets.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Palmetto","spirit":"rum","base":"Rum","family":"spirit-forward","spec":"60 ml aged rum; 30 ml sweet vermouth; 2 dashes orange bitters","method":"Stir with ice; strain into a chilled coupe; orange twist.","taste":"Rum’s cane and oak framed by sweet vermouth and orange bitters.","history":"A rum-led Manhattan relative appearing in early 20th-century cocktail literature; exact origin is uncertain.","glass":"Coupe","origin":"A rum-led Manhattan relative appearing in early 20th-century cocktail literature; exact origin is uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Paradise","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"7 parts Gin; 4 parts Apricot Brandy; 3 parts Orange Juice","method":"Shake together over ice. Strain into cocktail glass and serve chilled.","taste":"Orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Paradise. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Pegu Club","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 15 ml orange curaçao; 22.5 ml lime juice; 7.5 ml simple syrup; 1 dash aromatic bitters; 1 dash orange bitters","method":"Shake with ice; fine-strain into a chilled coupe; express a lime or orange peel.","taste":"Bright lime and orange, aromatic bitters and dry botanical structure; tart with a gently bitter finish.","history":"Named for the Pegu Club in Rangoon (now Yangon), a British colonial-era social club. The drink appears in early 20th-century bar manuals; exact inventor is uncertain.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Pink Lady","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"44.4 ml Gin; 4.9 ml Grenadine; 4.9 ml Light cream; 1 Egg white","method":"Shake all ingredients with ice, strain into a cocktail glass, and serve.","taste":"Rounded sweetness, soft, creamy texture. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Pink Lady. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Pisco Punch","spirit":"pisco","base":"Pisco","family":"punch","spec":"60 ml pisco; 25 ml pineapple syrup; 20 ml lemon juice; 10 ml simple syrup","method":"Shake with ice; strain into a chilled coupe; garnish pineapple.","taste":"Floral grape spirit with pineapple, citrus and gentle sweetness.","history":"A 19th-century San Francisco drink associated with Duncan Nicol at the Bank Exchange; its original recipe was a closely guarded secret.","glass":"Coupe","origin":"A 19th-century San Francisco drink associated with Duncan Nicol at the Bank Exchange; its original recipe was a closely guarded secret.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Planter's Punch Royal","spirit":"jamaican rum","base":"Jamaican rum","family":"punch","spec":"60 ml aged Jamaican rum; 20 ml lime juice; 20 ml orange juice; 15 ml demerara syrup; 30 ml pineapple juice; 2 dashes Angostura bitters","method":"Shake with crushed ice; pour into a tall glass; garnish mint and seasonal fruit.","taste":"Full cane character, layered citrus and warm spice; sweet-tart and refreshing.","history":"A variation on the Caribbean Planter’s Punch family; “royal” recipes differ and have no single verified origin.","glass":"Coupe / rocks","origin":"A variation on the Caribbean Planter’s Punch family; “royal” recipes differ and have no single verified origin.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Porto Flip","spirit":"brandy","base":"Brandy","family":"spirit-forward","spec":"45 ml ruby or tawny Port; 30 ml brandy; 15 ml whole egg","method":"Shake hard with ice; fine-strain into a chilled coupe; grate nutmeg.","taste":"Rich, vinous and silky, with dried fruit, grape, brandy warmth and nutmeg.","history":"Flip drinks—spirit or wine shaken with egg and often sugar—were common in 18th- and 19th-century drink culture. A Porto Flip appears in Jerry Thomas’s 19th-century bartending literature.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Queen's Park Swizzle","spirit":"demerara rum","base":"Demerara rum","family":"tropical","spec":"60 ml aged rum; 22.5 ml lime juice; 15 ml demerara syrup; mint; 2 dashes Angostura bitters","method":"Build in a tall glass with crushed ice; swizzle until frosty; add bitters on top and mint bouquet.","taste":"Rich cane, lime, fresh mint and aromatic bitters.","history":"A Trinidad drink associated with the Queen’s Park Hotel in Port of Spain in the early 20th century; exact first recipe is debated.","glass":"Highball","origin":"A Trinidad drink associated with the Queen’s Park Hotel in Port of Spain in the early 20th century; exact first recipe is debated.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Remember the Maine","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"60 ml rye whiskey; 22.5 ml sweet vermouth; 15 ml cherry liqueur; 5 ml absinthe","method":"Stir with ice; strain into a chilled coupe; express lemon peel.","taste":"Rye spice, cherry, wine richness and anise.","history":"Published by Charles H. Baker Jr. in 1939 and named for the 1898 battleship; the recipe is documented, though its earlier origins are unclear.","glass":"Coupe","origin":"Published by Charles H. Baker Jr. in 1939 and named for the 1898 battleship; the recipe is documented, though its earlier origins are unclear.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Rising Sun","spirit":"tequila","base":"Tequila","family":"sour","spec":"45 ml blanco tequila; 20 ml yuzu or lemon juice; 15 ml orange liqueur; 10 ml honey syrup","method":"Shake with ice; strain into a chilled coupe; citrus twist.","taste":"Agave and bright citrus with floral honey and orange.","history":"A modern house-drink name used by multiple bars; no canonical historic origin is established.","glass":"Coupe / rocks","origin":"A modern house-drink name used by multiple bars; no canonical historic origin is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Rosita","spirit":"tequila","base":"Tequila","family":"bitter aperitivo","spec":"45 ml reposado tequila; 15 ml sweet vermouth; 15 ml dry vermouth; 15 ml Campari; 1 dash Angostura bitters","method":"Stir with ice; strain over a large cube; orange twist.","taste":"Agave, dry and sweet wine, bitter orange and warm spice.","history":"Published in Gary Regan’s 1990s cocktail writing; a tequila-led Negroni variation with a documented modern revival.","glass":"Coupe / rocks","origin":"Published in Gary Regan’s 1990s cocktail writing; a tequila-led Negroni variation with a documented modern revival.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Rum Old Fashioned","spirit":"rum","base":"Rum","family":"sour","spec":"44.4 ml Light rum; 4.9 ml 151 proof rum; 2.5 ml Powdered sugar; 1 dash Bitters; 4.9 ml Water; Twist of Lime peel","method":"Stir powdered sugar, water, and bitters in an old-fashioned glass. When sugar has dissolved add ice cubes and light rum. Add the twist of lime peel, float 151 proof rum on top, and serve.","taste":"Bright citrus, rounded sweetness, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Rum Old Fashioned. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Old-fashioned glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Rum Runner","spirit":"rum","base":"Rum","family":"tropical","spec":"44.4 ml Malibu rum; 29.6 ml Blackberry brandy; 3-4 oz Orange juice; 3-4 oz Pineapple juice; 3-4 oz Cranberry juice","method":"Mix all ingredients in glass & add ice.","taste":"Orange peel, rounded sweetness, tropical fruit. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Rum Runner. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Salty Dog","spirit":"gin","base":"Gin","family":"sour","spec":"147.9 ml Grapefruit juice; 44.4 ml Gin; 1.2 ml Salt","method":"Pour all ingredients over ice cubes in a highball glass. Stir well and serve. (Vodka may be substituted for gin, if preferred.)","taste":"Bright citrus, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Salty Dog. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Highball glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Scofflaw","spirit":"rye whiskey","base":"Rye whiskey","family":"sour","spec":"45 ml rye whiskey; 22.5 ml dry vermouth; 22.5 ml lemon juice; 15 ml grenadine; 2 dashes orange bitters","method":"Shake with ice; strain into a chilled coupe; lemon twist.","taste":"Dry rye, citrus, vermouth and pomegranate-fruit sweetness.","history":"Created at Harry’s New York Bar in Paris in 1924, during U.S. Prohibition; the word “scofflaw” was coined in 1920s temperance-era debate.","glass":"Coupe","origin":"Created at Harry’s New York Bar in Paris in 1924, during U.S. Prohibition; the word “scofflaw” was coined in 1920s temperance-era debate.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Sherry Cobbler","spirit":"sherry","base":"Sherry","family":"cobbler","spec":"90 ml amontillado or oloroso sherry; 15 ml simple syrup; 2 orange slices; seasonal berries","method":"Muddle orange lightly with syrup; add sherry and crushed ice; churn; garnish berries and mint.","taste":"Nutty wine, bright orange and fruit; refreshing, low-ABV and gently sweet.","history":"A 19th-century American classic that helped popularize the drinking straw; the earliest precise inventor is unknown.","glass":"Highball / cobbler","origin":"A 19th-century American classic that helped popularize the drinking straw; the earliest precise inventor is unknown.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Sherry Flip","spirit":"wine","base":"Wine","family":"spirit-forward","spec":"1 1/2 oz cream Sherry; 9.9 ml Light cream; 4.9 ml Powdered sugar; 1 whole Egg; to taste Nutmeg","method":"Shake all ingredients (except nutmeg) with ice and strain into a whiskey sour glass. Sprinkle nutmeg on top and serve.","taste":"Rounded sweetness, soft, creamy texture. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Sherry Flip. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Nick and Nora Glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Sherry Sour","spirit":"sherry","base":"Sherry","family":"sour","spec":"60 ml oloroso or amontillado sherry; 25 ml lemon juice; 15 ml simple syrup; 15 ml egg white, optional","method":"Dry shake if using egg; shake with ice; fine-strain into a chilled coupe.","taste":"Nutty oxidative wine, fresh lemon and soft foam; lower in alcohol than a spirit sour.","history":"A flexible sour family using sherry; recipes are not tied to one reliably documented inventor.","glass":"Coupe / rocks","origin":"A flexible sour family using sherry; recipes are not tied to one reliably documented inventor.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Singapore Sling Classic","spirit":"gin","base":"Gin","family":"tropical","spec":"30 ml gin; 15 ml cherry liqueur; 7.5 ml orange liqueur; 7.5 ml Bénédictine; 7.5 ml grenadine; 15 ml lime juice; 120 ml pineapple juice; 1 dash aromatic bitters","method":"Shake with ice; strain over fresh ice in a highball; garnish pineapple and cherry.","taste":"Pineapple, cherry and spice around gin; long, fruity and gently tart.","history":"Associated with Ngiam Tong Boon at Raffles Hotel, Singapore, in the early 20th century; original formulas and later house versions differ.","glass":"Coupe / rocks","origin":"Associated with Ngiam Tong Boon at Raffles Hotel, Singapore, in the early 20th century; original formulas and later house versions differ.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Smoky Martini","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"60 ml gin; 10 ml dry vermouth; 5 ml peated Scotch whisky rinse or float","method":"Stir gin and vermouth with ice; strain into a chilled coupe lightly rinsed with peated Scotch.","taste":"Dry botanicals with a measured, aromatic smoke accent.","history":"A modern Martini variation; no single creator or standard smoke ratio is established.","glass":"Coupe / rocks","origin":"A modern Martini variation; no single creator or standard smoke ratio is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Suffering Bastard","spirit":"gin and brandy","base":"Gin and brandy","family":"highball","spec":"30 ml gin; 30 ml Cognac or brandy; 15 ml lime juice; 2 dashes Angostura bitters; 90 ml ginger beer","method":"Shake the spirits, lime and bitters briefly; strain over ice; top with ginger beer.","taste":"Juniper, grape spirit, lime and spicy ginger; dry and bracing.","history":"Credited to Joe Scialom at Cairo’s Shepheard’s Hotel in the 1940s; wartime origin details are widely repeated.","glass":"Coupe / rocks","origin":"Credited to Joe Scialom at Cairo’s Shepheard’s Hotel in the 1940s; wartime origin details are widely repeated.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Tuxedo No. 2","spirit":"gin","base":"Gin","family":"spirit-forward","spec":"60 ml gin; 20 ml dry vermouth; 5 ml maraschino liqueur; 2 dashes orange bitters; absinthe rinse","method":"Rinse a chilled coupe with absinthe; stir remaining ingredients with ice and strain; lemon twist.","taste":"Dry gin, floral wine, cherry and a delicate anise lift.","history":"Part of the Tuxedo cocktail family documented in the late 19th and early 20th centuries; recipes and numbering differ between sources.","glass":"Coupe","origin":"Part of the Tuxedo cocktail family documented in the late 19th and early 20th centuries; recipes and numbering differ between sources.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Vermouth Cocktail","spirit":"sweet vermouth","base":"Sweet vermouth","family":"spirit-forward","spec":"75 ml sweet vermouth; 2 dashes aromatic bitters; 1 dash orange bitters; soda splash optional","method":"Stir with ice; strain into a small chilled wine glass or serve over ice; orange twist.","taste":"Herbal, wine-led, aromatic and low in alcohol compared with spirit cocktails.","history":"Vermouth cocktails predate modern cocktail naming; this is a family template rather than a single attributable invention.","glass":"Small wine glass / rocks","origin":"Vermouth cocktails predate modern cocktail naming; this is a family template rather than a single attributable invention.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Ward Eight","spirit":"rye whiskey","base":"Rye whiskey","family":"sour","spec":"60 ml rye whiskey; 20 ml lemon juice; 15 ml orange juice; 15 ml grenadine","method":"Shake with ice; strain over fresh ice or into a chilled coupe; orange twist.","taste":"Rye spice, orange and lemon with a pomegranate-red sweet-tart finish.","history":"Associated with Boston in the late 19th century and Martin Lomasney’s political election; competing accounts describe its first service.","glass":"Coupe / rocks","origin":"Associated with Boston in the late 19th century and Martin Lomasney’s political election; competing accounts describe its first service.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Widow's Kiss","spirit":"apple brandy","base":"Apple brandy","family":"spirit-forward","spec":"45 ml apple brandy; 22.5 ml Bénédictine; 22.5 ml yellow Chartreuse; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Baked apple, herbal honey, spice and a long warming finish.","history":"Published by George Kappeler in 1895 in Modern American Drinks; a documented late-19th-century cocktail.","glass":"Coupe","origin":"Published by George Kappeler in 1895 in Modern American Drinks; a documented late-19th-century cocktail.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Yellow Bird","spirit":"rum","base":"Rum","family":"sour","spec":"30 ml White Rum; 15 ml Galliano; 15 ml Triple Sec; 15 ml Lime Juice","method":"Shake and strain into a chilled cocktail glass","taste":"Bright citrus, orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Yellow Bird. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"B52","spirit":"spirit","base":"Spirit","family":"spirit-forward","spec":"1/3 Baileys irish cream; 1/3 Grand Marnier; 1/4 Kahlua","method":"Layer ingredients into a shot glass. Serve with a stirrer.","taste":"Rounded sweetness, soft, creamy texture. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for B52. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Shot glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Bacardi Cocktail","spirit":"rum","base":"Rum","family":"sour","spec":"50 ml white Bacardí-style rum; 25 ml lime juice; 15 ml simple syrup; 5 ml grenadine, optional","method":"Shake with ice; fine-strain into a chilled coupe. Use the specified rum style where the house recipe calls for it.","taste":"Light cane, lime acidity and a gentle red-fruit sweetness; tart, crisp and aromatic.","history":"A rum sour with grenadine was popular in the early 20th century. A 1936 New York court decision required drinks ordered as a “Bacardi cocktail” there to use Bacardí rum; this is a trade-name/legal history, not proof of invention.","glass":"Cocktail glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Barracuda","spirit":"rum","base":"Rum","family":"sour","spec":"45 ml Rum; 15 ml Galliano; 60 ml Pineapple Juice; 1 dash Lime Juice; top up Prosecco","method":"Shake pour ingredients with ice. Strain into glass, top with Sparkling wine.","taste":"Bright citrus, rounded sweetness, tropical fruit, lively bubbles. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Barracuda. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Margarita glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Batanga","spirit":"blanco tequila","base":"Blanco tequila","family":"highball","spec":"50 ml blanco tequila; 15 ml lime juice; 120 ml cola; pinch of salt","method":"Build over ice in a highball; top with cola and stir gently; lime wedge.","taste":"Agave, cola spice, lime and a light saline edge.","history":"Associated with Don Javier Delgado Corona and La Capilla bar in Tequila, Jalisco; the exact date is not consistently recorded.","glass":"Highball","origin":"Associated with Don Javier Delgado Corona and La Capilla bar in Tequila, Jalisco; the exact date is not consistently recorded.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Bee Sting","spirit":"gin","base":"Gin","family":"sour","spec":"60 ml gin; 25 ml lemon juice; 20 ml honey syrup; 1 dash aromatic bitters","method":"Shake with ice; strain into a chilled coupe; lemon twist.","taste":"Honey, lemon and botanical gin with a soft spice finish.","history":"A modern name used for several honey-gin sours; no single verified origin is asserted.","glass":"Coupe / rocks","origin":"A modern name used for several honey-gin sours; no single verified origin is asserted.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Betsy Ross","spirit":"brandy","base":"Brandy","family":"spirit-forward","spec":"45 ml brandy; 30 ml ruby port; 10 ml orange liqueur; 2 dashes aromatic bitters","method":"Stir with ice; strain into a chilled coupe; orange twist.","taste":"Grape spirit and port richness with orange and spice.","history":"A historic American cocktail name appearing in early 20th-century books; proportions and first-creation story vary.","glass":"Coupe / rocks","origin":"A historic American cocktail name appearing in early 20th-century books; proportions and first-creation story vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Blackthorn","spirit":"gin","base":"Gin","family":"bitter aperitivo","spec":"29.6 ml Sweet Vermouth; 44.4 ml Sloe gin; 1 twist of Lemon peel","method":"Stir sloe gin and vermouth with ice and strain into a cocktail glass. Add the twist of lemon peel and serve.","taste":"Bright citrus, bitter-herbal structure. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Blackthorn. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Cocktail glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Blood and Sand","spirit":"scotch whisky","base":"Scotch whisky","family":"sour","spec":"30 ml Scotch whisky; 30 ml sweet vermouth; 30 ml cherry liqueur; 30 ml orange juice","method":"Shake with ice; fine-strain into a chilled coupe; orange twist.","taste":"Malt, cherry, orange and vermouth spice; softly fruity and rounded.","history":"Named after the 1922 bullfighting film Blood and Sand; one of the few classic cocktails built around Scotch and orange juice.","glass":"Coupe","origin":"Named after the 1922 bullfighting film Blood and Sand; one of the few classic cocktails built around Scotch and orange juice.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Blue Hawaii","spirit":"rum","base":"Rum","family":"tropical","spec":"30 ml light rum; 30 ml vodka; 15 ml blue curaçao; 90 ml pineapple juice; 30 ml sour mix","method":"Shake with ice; strain over fresh ice; garnish pineapple and cherry.","taste":"Pineapple, citrus and orange liqueur; sweet-tart and tropical.","history":"Created by Harry Yee at the Hawaiian Village Hotel in Honolulu in 1957 to showcase blue curaçao.","glass":"Hurricane / highball","origin":"Created by Harry Yee at the Hawaiian Village Hotel in Honolulu in 1957 to showcase blue curaçao.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Blue Lagoon","spirit":"vodka","base":"Vodka","family":"spirit-forward","spec":"45 ml vodka; 15 ml blue curaçao; 15 ml lemon juice; 60 ml lemonade or soda, to taste","method":"Shake vodka, curaçao and lemon with ice; strain over fresh ice in a highball; top with lemonade.","taste":"Orange-citrus sweetness, lemon brightness and a clean spirit base; lemonade makes it softer and longer.","history":"The Blue Lagoon became a popular 20th-century blue curaçao highball. Attributions to Paris bars circulate, but a definitive first creator and date are not securely established.","glass":"Highball glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Bourbon Renewal","spirit":"bourbon","base":"Bourbon","family":"sour","spec":"60 ml bourbon; 22.5 ml lemon juice; 15 ml crème de cassis; 15 ml simple syrup; 1 dash Angostura bitters","method":"Shake with ice; strain over a large cube; lemon twist.","taste":"Bourbon, blackcurrant, lemon and bitters; tart, fruity and structured.","history":"Created by Jeffrey Morgenthaler at the Bel Ami Lounge in Eugene, Oregon, in the early 2000s.","glass":"Rocks","origin":"Created by Jeffrey Morgenthaler at the Bel Ami Lounge in Eugene, Oregon, in the early 2000s.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Brandy Alexander","spirit":"brandy","base":"Brandy","family":"spirit-forward","spec":"30 ml brandy; 30 ml dark crème de cacao; 30 ml cream; fresh nutmeg","method":"Shake with ice; fine-strain into a chilled coupe; grate nutmeg.","taste":"Creamy cocoa and nutmeg soften grape-spirit fruit and oak; dessert-like but balanced by the brandy.","history":"The Alexander family appeared in early 20th-century cocktail culture. The brandy version developed from gin-based Alexander recipes; accounts of its exact creator and first occasion vary.","glass":"Whiskey Glass","origin":"Historical note is cautious; exact origin may be disputed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish","recipeReference":"TheCocktailDB listing cross-check; Pourfolio measured house spec"},{"name":"Brandy Daisy","spirit":"brandy","base":"Brandy","family":"daisy","spec":"60 ml brandy; 20 ml lemon juice; 15 ml orange liqueur; 10 ml simple syrup; soda water","method":"Shake first four ingredients with ice; strain over fresh ice; top with soda.","taste":"Brandy fruit, lemon and orange with a light sparkling finish.","history":"A Daisy is a 19th-century cocktail family; brandy versions appear in classic bartending books. Exact first creation is unclear.","glass":"Highball","origin":"A Daisy is a 19th-century cocktail family; brandy versions appear in classic bartending books. Exact first creation is unclear.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Breakfast Martini","spirit":"gin","base":"Gin","family":"sour","spec":"50 ml gin; 15 ml orange liqueur; 15 ml lemon juice; 1 tsp orange marmalade","method":"Shake with ice until marmalade dissolves; fine-strain into a chilled coupe; orange twist.","taste":"Gin botanicals, marmalade bitterness, orange and bright lemon.","history":"Created by Salvatore Calabrese in London in 1996, inspired by toast and marmalade at breakfast.","glass":"Coupe","origin":"Created by Salvatore Calabrese in London in 1996, inspired by toast and marmalade at breakfast.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Brown Derby","spirit":"bourbon","base":"Bourbon","family":"sour","spec":"60 ml bourbon; 30 ml grapefruit juice; 15 ml honey syrup","method":"Shake with ice; fine-strain into a chilled coupe; grapefruit twist.","taste":"Bourbon warmth and grapefruit bitterness softened with honey.","history":"Associated with Hollywood’s Vendôme Club and the Brown Derby restaurant in 1930s Los Angeles; publication records support the era.","glass":"Coupe","origin":"Associated with Hollywood’s Vendôme Club and the Brown Derby restaurant in 1930s Los Angeles; publication records support the era.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Café Royale","spirit":"brandy","base":"Brandy","family":"coffee","spec":"30 ml brandy; 120 ml hot coffee; 1 tsp sugar; lightly whipped cream, optional","method":"Dissolve sugar in coffee; add brandy; float cream if desired.","taste":"Roasted coffee, warming grape spirit and gentle creaminess.","history":"A broad coffee-and-spirit service style; recipes and naming conventions vary by country and era.","glass":"Coupe / rocks","origin":"A broad coffee-and-spirit service style; recipes and naming conventions vary by country and era.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Calvados Cocktail","spirit":"calvados","base":"Calvados","family":"spirit-forward","spec":"60 ml Calvados; 15 ml dry vermouth; 7.5 ml orange liqueur; 2 dashes orange bitters","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Apple and pear brandy with dry wine and orange peel.","history":"A broad family of apple-brandy cocktails; individual formulas vary and a single first creator is not established.","glass":"Coupe","origin":"A broad family of apple-brandy cocktails; individual formulas vary and a single first creator is not established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Carajillo","spirit":"licor 43","base":"Licor 43","family":"coffee","spec":"45 ml Licor 43; 30 ml espresso","method":"Shake briefly with ice for a chilled carajillo or build hot in a small glass; serve promptly.","taste":"Coffee bitterness, vanilla, citrus and warm spice.","history":"A Spanish and Latin American coffee-and-spirit tradition with several regional forms; exact origin stories are contested.","glass":"Rocks / small glass","origin":"A Spanish and Latin American coffee-and-spirit tradition with several regional forms; exact origin stories are contested.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Clover Leaf","spirit":"gin","base":"Gin","family":"sour","spec":"45 ml gin; 20 ml raspberry syrup; 22.5 ml lemon juice; 20 ml egg white","method":"Dry shake; add ice and shake again; fine-strain into a chilled coupe.","taste":"Raspberry fruit, lemon and silky foam over botanical gin.","history":"A pre-Prohibition Philadelphia-area Clover Club variation; similar recipes appear in early 20th-century cocktail books.","glass":"Coupe","origin":"A pre-Prohibition Philadelphia-area Clover Club variation; similar recipes appear in early 20th-century cocktail books.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Coconut Daiquiri","spirit":"white rum","base":"White rum","family":"sour","spec":"60 ml white rum; 25 ml lime juice; 15 ml coconut cream; 10 ml simple syrup","method":"Shake hard with ice; fine-strain into a chilled coupe.","taste":"Fresh lime and cane with a soft coconut texture.","history":"A modern tropical riff on the Daiquiri family; exact first creation is not established.","glass":"Coupe","origin":"A modern tropical riff on the Daiquiri family; exact first creation is not established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Cointreau Teese","spirit":"vodka","base":"Vodka","family":"sour","spec":"45 ml vodka; 20 ml orange liqueur; 20 ml lime juice; 20 ml cranberry juice; 10 ml simple syrup","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Orange oil, tart cranberry and lime over a clean vodka base.","history":"A contemporary branded cocktail name with varying published specs; exact first creator is not independently verified.","glass":"Coupe / rocks","origin":"A contemporary branded cocktail name with varying published specs; exact first creator is not independently verified.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Corpse Reviver No. 1","spirit":"cognac","base":"Cognac","family":"spirit-forward","spec":"30 ml Cognac; 30 ml Calvados; 30 ml sweet vermouth","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Apple brandy, grape spirit and bittersweet wine; warming and aromatic.","history":"A pre-Prohibition reviver recipe published by Harry Craddock in the 1930 Savoy Cocktail Book; older variants existed.","glass":"Coupe","origin":"A pre-Prohibition reviver recipe published by Harry Craddock in the 1930 Savoy Cocktail Book; older variants existed.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Cynar Spritz","spirit":"cynar","base":"Cynar","family":"spritz","spec":"60 ml Cynar; 90 ml Prosecco; 30 ml soda water","method":"Build over ice in a wine glass; add soda gently; orange slice.","taste":"Herbal artichoke amaro, wine bubbles and a bittersweet citrus finish.","history":"A contemporary spritz variation; no single inventor or origin date is established.","glass":"Wine glass","origin":"A contemporary spritz variation; no single inventor or origin date is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Daiquiri No. 3","spirit":"white rum","base":"White rum","family":"sour","spec":"60 ml white rum; 15 ml maraschino liqueur; 15 ml grapefruit juice; 15 ml lime juice; 5 ml simple syrup","method":"Shake with ice; fine-strain into a chilled coupe.","taste":"Dry rum, tart grapefruit and lime with a subtle cherry note.","history":"A Hemingway-style Daiquiri variation associated with El Floridita; published specs differ over time.","glass":"Coupe","origin":"A Hemingway-style Daiquiri variation associated with El Floridita; published specs differ over time.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Don's Special Daiquiri","spirit":"rum","base":"Rum","family":"tropical","spec":"45 ml aged rum; 20 ml lime juice; 15 ml passion-fruit syrup; 10 ml honey syrup; 7.5 ml falernum; 1 dash grenadine","method":"Shake with crushed ice; pour into a small tiki glass; garnish mint.","taste":"Aged cane, passion fruit, lime and warm baking spice; vivid and layered.","history":"A Don the Beachcomber-era tiki recipe; versions vary because early house formulas were guarded.","glass":"Coupe / rocks","origin":"A Don the Beachcomber-era tiki recipe; versions vary because early house formulas were guarded.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"El Diablo","spirit":"blanco tequila","base":"Blanco tequila","family":"highball","spec":"45 ml blanco tequila; 15 ml crème de cassis; 15 ml lime juice; 90 ml ginger beer","method":"Shake tequila, cassis and lime briefly; strain over ice; top with ginger beer.","taste":"Agave, blackcurrant, lime and spicy ginger; lively sweet-tart balance.","history":"A tequila highball published in Trader Vic’s 1946 Bartender’s Guide; later versions vary.","glass":"Highball","origin":"A tequila highball published in Trader Vic’s 1946 Bartender’s Guide; later versions vary.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"El Pepino","spirit":"blanco tequila","base":"Blanco tequila","family":"sour","spec":"50 ml blanco tequila; 25 ml lime juice; 15 ml agave syrup; cucumber; 6 mint leaves","method":"Muddle cucumber lightly; shake all ingredients with ice; double-strain into a coupe.","taste":"Cool cucumber, mint and lime against fresh agave.","history":"A contemporary cucumber-tequila sour family; no single definitive first-creation record is established.","glass":"Coupe","origin":"A contemporary cucumber-tequila sour family; no single definitive first-creation record is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Enzoni Spritz","spirit":"gin","base":"Gin","family":"spritz","spec":"30 ml gin; 20 ml Campari; 20 ml lemon juice; 10 ml simple syrup; 4 green grapes; 60 ml Prosecco","method":"Muddle grapes gently; shake gin, Campari, lemon and syrup with ice; strain over ice and top Prosecco.","taste":"Fresh grape, bitter orange, lemon and sparkling wine.","history":"A modern spritz riff on the Enzoni; no single original date is established.","glass":"Coupe / rocks","origin":"A modern spritz riff on the Enzoni; no single original date is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Fanciulli","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"60 ml rye whiskey; 30 ml sweet vermouth; 7.5 ml Fernet-Branca","method":"Stir with ice; strain into a chilled coupe; orange twist.","taste":"Rye spice, vermouth richness and firm bitter mint/herb notes.","history":"A Manhattan variation appearing in early 20th-century cocktail books; exact naming origin is uncertain.","glass":"Coupe / rocks","origin":"A Manhattan variation appearing in early 20th-century cocktail books; exact naming origin is uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Gin & Tonic","spirit":"gin","base":"Gin","family":"highball","spec":"50 ml gin; 120 ml chilled tonic water; citrus garnish","method":"Build gin over ice in a chilled highball; add tonic gently; lift once.","taste":"Bitter-sweet quinine, botanicals and citrus, highly adjustable.","history":"The gin-and-tonic grew from British colonial-era tonic-water use; modern commercial tonic differs greatly from historical quinine mixtures.","glass":"Coupe / rocks","origin":"Historical note: The gin-and-tonic grew from British colonial-era tonic-water use; modern commercial tonic differs greatly from historical quinine mixtures.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Gin Daisy","spirit":"gin","base":"Gin","family":"sour","spec":"59.1 ml Gin; 29.6 ml Lemon juice; 1/2 tsp superfine Sugar; 2.5 ml Grenadine; 1 Maraschino cherry; 1 Orange","method":"In a shaker half-filled with ice cubes, combine the gin, lemon juice, sugar, and grenadine. Shake well. Pour into an old-fashioned glass and garnish with the cherry and the orange slice.","taste":"Bright citrus, orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Gin Daisy. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Old-fashioned glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Gin Sour","spirit":"gin","base":"Gin","family":"sour","spec":"59.1 ml Gin; 29.6 ml Lemon juice; 1/2 tsp superfine Sugar; 1 Orange; 1 Maraschino cherry","method":"In a shaker half-filled with ice cubes, combine the gin, lemon juice, and sugar. Shake well. Strain into a sour glass and garnish with the orange slice and the cherry.","taste":"Bright citrus, orange peel, rounded sweetness. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Gin Sour. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Whiskey sour glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Grand Margarita","spirit":"blanco tequila","base":"Blanco tequila","family":"sour","spec":"45 ml tequila; 30 ml Grand Marnier; 20 ml lime juice; 5 ml agave syrup, optional","method":"Shake with ice; strain over fresh ice; salt rim optional.","taste":"Agave and lime with cognac-based orange liqueur richness.","history":"A premium Margarita variation; recipes and brand specifications vary, with no unique inventor established.","glass":"Rocks","origin":"A premium Margarita variation; recipes and brand specifications vary, with no unique inventor established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Greenpoint","spirit":"rye whiskey","base":"Rye whiskey","family":"spirit-forward","spec":"45 ml rye whiskey; 22.5 ml sweet vermouth; 7.5 ml yellow Chartreuse; 1 dash Angostura bitters; 1 dash orange bitters","method":"Stir with ice; strain into a chilled coupe; lemon twist.","taste":"Rye spice, herbal honey, wine and layered bitters.","history":"Created by Michael McIlroy at Milk & Honey in New York in 2006; named for the Brooklyn neighborhood.","glass":"Coupe","origin":"Created by Michael McIlroy at Milk & Honey in New York in 2006; named for the Brooklyn neighborhood.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Hurricane","spirit":"rum","base":"Rum","family":"tropical","spec":"60 ml dark rum; 30 ml white rum; 30 ml passion-fruit syrup; 25 ml lemon juice; 15 ml orange juice","method":"Shake with ice; strain over crushed ice in a hurricane glass; garnish orange and cherry.","taste":"Passion fruit, citrus and rum; lush, tart-sweet and tropical.","history":"Associated with Pat O’Brien’s in New Orleans around World War II; the glass and recipe changed as rum availability shifted.","glass":"Hurricane","origin":"Associated with Pat O’Brien’s in New Orleans around World War II; the glass and recipe changed as rum availability shifted.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Irish Maid","spirit":"irish whiskey","base":"Irish whiskey","family":"sour","spec":"60 ml Irish whiskey; 20 ml elderflower liqueur; 22.5 ml lemon juice; 15 ml simple syrup; cucumber","method":"Muddle cucumber lightly; shake with ice; strain over fresh ice; cucumber garnish.","taste":"Soft whiskey, elderflower, lemon and cooling cucumber.","history":"A modern Irish whiskey cocktail in the Maid family; no single verified first-creation record is established.","glass":"Rocks","origin":"A modern Irish whiskey cocktail in the Maid family; no single verified first-creation record is established.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"},{"name":"Dark and Stormy","spirit":"gin","base":"Gin","family":"highball","spec":"50 ml Dark Rum; 100 ml Ginger Beer","method":"In a highball glass filled with ice add 6cl dark rum and top with ginger beer. Garnish with lime wedge.","taste":"Lively bubbles. Taste and intensity vary with the specific products and dilution.","history":"The recipe listing source does not establish a verified first-creation date, place or inventor for Dark and Stormy. Treat any origin legend as unconfirmed unless supported by historical evidence.","glass":"Highball glass","origin":"Origin: not verified in the recipe source; no single creator or date asserted.","source":"TheCocktailDB recipe listing","garnish":"Ingredient-led garnish"},{"name":"Godfather","spirit":"whiskey","base":"Whiskey","family":"spirit-forward","spec":"45 ml Scotch whisky; 25 ml amaretto","method":"Build over ice in a rocks glass; stir gently.","taste":"Nutty sweetness over malt and oak.","history":"A 1970s-era two-ingredient drink. The name is often linked to the film, but the precise naming story is uncertain.","glass":"Coupe / rocks","origin":"Historical note: A 1970s-era two-ingredient drink. The name is often linked to the film, but the precise naming story is uncertain.","source":"Pourfolio editorial spec","garnish":"Ingredient-led garnish"}];
